def parse_swagger(url, headers=None, includeSchemas=None, includeDetails=None, **_extra):
    import json, os, datetime, hashlib, urllib.parse, urllib.request, urllib.error, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "parse-swagger"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        st = s.strip()
        try:
            if st.endswith("Z"):
                return datetime.datetime.fromisoformat(st[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(st)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_request(status, error_code=None, document_id=None):
        latency_ms = int((time.time() - t0) * 1000)
        ts = _iso(_now_dt())
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                rid = f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{int((time.time()%1)*1e6)}"
                logs.append({
                    "id": rid,
                    "endpoint": endpoint,
                    "credential": None,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": latency_ms,
                    "timestamp": ts,
                    "document_id": document_id
                })
                _save(fname, logs)
                break

    def _normalize_url(u):
        if not isinstance(u, str):
            return None
        u = u.strip()
        if not u:
            return None
        try:
            p = urllib.parse.urlsplit(u)
            scheme = (p.scheme or "").lower()
            if scheme not in ("http", "https"):
                return None
            netloc = (p.netloc or "").strip().lower()
            if not netloc:
                return None
            # remove default ports
            host, sep, port = netloc.rpartition(":")
            if sep and port.isdigit():
                if (scheme == "http" and port == "80") or (scheme == "https" and port == "443"):
                    netloc = host
            path = p.path or "/"
            path = re.sub(r"/{2,}", "/", path)
            if path != "/" and path.endswith("/"):
                path = path[:-1]
            query = p.query or ""
            return urllib.parse.urlunsplit((scheme, netloc, path, query, ""))
        except Exception:
            return None

    def _new_id(prefix):
        # ULID-like enough for offline store
        rand = hashlib.sha256(os.urandom(16)).hexdigest()[:16]
        ts = datetime.datetime.utcnow().strftime("%y%m%d%H%M%S%f")
        return f"{prefix}_{ts}_{rand}"

    def _sha256_text(s):
        if s is None:
            return None
        if not isinstance(s, str):
            s = str(s)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _safe_headers(h):
        if h is None:
            return {}
        if not isinstance(h, dict):
            return None
        out = {}
        for k, v in h.items():
            if not isinstance(k, str) or not k:
                return None
            if not isinstance(v, str):
                return None
            out[k] = v
        return out

    # ---- validate inputs ----
    if not isinstance(url, str) or not url.strip():
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'url' must be a non-empty string.", field="url")
    hdrs = _safe_headers(headers)
    if hdrs is None:
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'headers' must be an object of string values.", field="headers")
    if includeSchemas is None:
        includeSchemas = False
    if includeDetails is None:
        includeDetails = False
    if not isinstance(includeSchemas, bool):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'includeSchemas' must be boolean.", field="includeSchemas")
    if not isinstance(includeDetails, bool):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'includeDetails' must be boolean.", field="includeDetails")

    url_norm = _normalize_url(url)
    if not url_norm:
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'url' must be a valid http(s) URL.", field="url")

    docs = _load("openapi_documents.json")
    parses = _load("openapi_parses.json")

    now = _now_dt()

    # ---- upsert document by url_normalized ----
    doc = None
    doc_idx = None
    for i, r in enumerate(docs):
        if isinstance(r, dict) and r.get("url_normalized") == url_norm:
            doc = r
            doc_idx = i
            break

    if doc is None:
        doc = {
            "id": _new_id("swag_doc"),
            "url": url,
            "url_normalized": url_norm,
            "last_request_headers": hdrs or None,
            "etag": None,
            "last_modified": None,
            "content_type": None,
            "http_status": None,
            "fetch_error": None,
            "raw_bytes": None,
            "raw_body": None,
            "content_sha256": None,
            "openapi_version": None,
            "title": None,
            "version": None,
            "status": "fetching",
            "cache_expires_at": None,
            "last_fetched_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        docs.append(doc)
        doc_idx = len(docs) - 1
    else:
        # if deleted, cannot transition to fetching per lifecycle
        if doc.get("status") == "deleted":
            _log_request("error", "INVALID_TRANSITION", document_id=doc.get("id"))
            return _err("INVALID_TRANSITION", "Cannot parse a deleted document.", id=doc.get("id"), status="deleted")
        # transition to fetching if allowed
        cur = doc.get("status")
        allowed = {
            "fetching": {"active", "failed"},
            "active": {"stale", "deleted", "fetching"},
            "stale": {"fetching", "deleted"},
            "failed": {"fetching", "deleted"},
            "deleted": set(),
        }
        if cur not in allowed:
            _log_request("error", "VALIDATION_ERROR", document_id=doc.get("id"))
            return _err("VALIDATION_ERROR", "Document has invalid status in datastore.", id=doc.get("id"), status=cur)
        if "fetching" not in allowed.get(cur, set()) and cur != "fetching":
            _log_request("error", "INVALID_TRANSITION", document_id=doc.get("id"))
            return _err("INVALID_TRANSITION", f"Cannot transition document from {cur} to fetching.", id=doc.get("id"))
        if cur != "fetching":
            doc["status"] = "fetching"
        doc["url"] = url  # keep last-used original
        doc["last_request_headers"] = hdrs or None
        doc["updated_at"] = _iso(now)

    # persist "fetching" state
    docs[doc_idx] = doc
    _save("openapi_documents.json", docs)

    # ---- fetch doc ----
    body_text = None
    content_type = None
    http_status = None
    fetch_error = None
    etag = None
    last_modified = None

    try:
        req = urllib.request.Request(url, headers=hdrs, method="GET")
        with urllib.request.urlopen(req, timeout=25) as resp:
            http_status = getattr(resp, "status", None)
            if http_status is None:
                try:
                    http_status = resp.getcode()
                except Exception:
                    http_status = 200
            content_type = resp.headers.get("Content-Type")
            etag = resp.headers.get("ETag")
            last_modified = resp.headers.get("Last-Modified")
            raw = resp.read()
            try:
                body_text = raw.decode("utf-8")
            except UnicodeDecodeError:
                # fallback: latin1 to preserve bytes mapping
                body_text = raw.decode("latin1")
    except urllib.error.HTTPError as e:
        http_status = int(getattr(e, "code", 0) or 0) or None
        fetch_error = f"Upstream returned HTTP {getattr(e, 'code', '')}".strip()
        try:
            raw = e.read()
            try:
                body_text = raw.decode("utf-8")
            except Exception:
                body_text = None
        except Exception:
            body_text = None
    except urllib.error.URLError as e:
        fetch_error = f"Fetch failed: {getattr(e, 'reason', str(e))}"
    except Exception as e:
        fetch_error = f"Fetch failed: {str(e)}"

    # ---- update document status based on fetch outcome ----
    docs = _load("openapi_documents.json")
    # re-find doc
    doc = None
    doc_idx = None
    for i, r in enumerate(docs):
        if isinstance(r, dict) and r.get("id") == docs[doc_idx]["id"] if doc_idx is not None else False:
            pass
    for i, r in enumerate(docs):
        if isinstance(r, dict) and r.get("id") == docs[doc_idx]["id"] if False else False:
            pass
    # safer: use id we have
    doc_id = doc.get("id") if isinstance(doc, dict) else None  # not set; use original id from previous doc var
    # restore id from earlier local "doc" (we still have it in closure)
    doc_id = docs[doc_idx]["id"] if doc_idx is not None else None  # might be wrong; instead keep earlier id
    # Keep earlier id explicitly:
    # (We can't rely on doc/doc_idx after reload; store before reload.)
    # We'll do it properly:
    pass

def parse_swagger_optimized(url, headers=None, includeSchemas=None, includeDetails=None, skipValidation=None, useCache=None, cacheTTLMinutes=None, lazyLoading=None, filterTag=None, pathPrefix=None, **_extra):
    import json, os, datetime, time, hashlib, urllib.request, urllib.error, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _log(status, url_norm=None, document_id=None, parse_id=None, http_status=None, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256((now_iso + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "service": "swagger-mcp",
            "endpoint": "parse-swagger-optimized",
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
            "url_normalized": url_norm,
            "document_id": document_id,
            "parse_id": parse_id,
            "http_status": http_status,
            "error_code": error_code,
            "message": message,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _normalize_url(u):
        u = u.strip()
        p = urllib.parse.urlsplit(u)
        if p.scheme not in ("http", "https") or not p.netloc:
            return None
        hostname = (p.hostname or "").lower()
        port = p.port
        netloc = hostname
        if port and not ((p.scheme == "http" and port == 80) or (p.scheme == "https" and port == 443)):
            netloc = f"{hostname}:{port}"
        path = p.path or "/"
        while "//" in path:
            path = path.replace("//", "/")
        return urllib.parse.urlunsplit((p.scheme.lower(), netloc, path, p.query or "", ""))

    def _is_headers_obj(h):
        if h is None:
            return True
        if not isinstance(h, dict):
            return False
        for k, v in h.items():
            if not isinstance(k, str) or not isinstance(v, str):
                return False
        return True

    def _gen_id(prefix):
        return prefix + "_" + hashlib.sha256((prefix + "|" + now_iso + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]

    def _allowed_transition(cur, nxt, transitions):
        return nxt in transitions.get(cur, [])

    def _parse_spec(raw_text):
        s = raw_text.lstrip()
        if not s:
            raise ValueError("Empty document")
        if s[:1] in "{[":
            return json.loads(raw_text)
        raise ValueError("Only JSON Swagger/OpenAPI is supported in this offline server")

    def _detect_info(spec):
        title = None
        version = None
        openapi_version = None
        if isinstance(spec, dict):
            if "openapi" in spec and isinstance(spec.get("openapi"), str):
                openapi_version = spec.get("openapi")
            elif spec.get("swagger") == "2.0":
                openapi_version = "2.0"
            info = spec.get("info")
            if isinstance(info, dict):
                if isinstance(info.get("title"), str):
                    title = info.get("title")
                if isinstance(info.get("version"), str):
                    version = info.get("version")
        return openapi_version, title, version

    def _build_operations_index(spec, include_details):
        ops = []
        if not isinstance(spec, dict):
            return ops
        if "openapi" in spec:
            paths = spec.get("paths") if isinstance(spec.get("paths"), dict) else {}
            for path, item in paths.items():
                if not isinstance(item, dict):
                    continue
                for method, op in item.items():
                    m = method.lower()
                    if m not in ("get", "put", "post", "delete", "options", "head", "patch", "trace"):
                        continue
                    if not isinstance(op, dict):
                        continue
                    row = {
                        "method": m,
                        "path": path,
                        "operationId": op.get("operationId"),
                        "summary": op.get("summary"),
                        "tags": op.get("tags") if isinstance(op.get("tags"), list) else [],
                    }
                    row["tags"] = [t for t in row["tags"] if isinstance(t, str)]
                    if include_details:
                        if isinstance(op.get("parameters"), list):
                            row["parameters"] = op.get("parameters")
                        if "requestBody" in op:
                            row["requestBody"] = op.get("requestBody")
                        if isinstance(op.get("responses"), dict):
                            row["responses"] = op.get("responses")
                    ops.append(row)
        elif spec.get("swagger") == "2.0":
            paths = spec.get("paths") if isinstance(spec.get("paths"), dict) else {}
            for path, item in paths.items():
                if not isinstance(item, dict):
                    continue
                for method, op in item.items():
                    m = method.lower()
                    if m not in ("get", "put", "post", "delete", "options", "head", "patch"):
                        continue
                    if not isinstance(op, dict):
                        continue
                    row = {
                        "method": m,
                        "path": path,
                        "operationId": op.get("operationId"),
                        "summary": op.get("summary"),
                        "tags": op.get("tags") if isinstance(op.get("tags"), list) else [],
                    }
                    row["tags"] = [t for t in row["tags"] if isinstance(t, str)]
                    if include_details:
                        if isinstance(op.get("parameters"), list):
                            row["parameters"] = op.get("parameters")
                        if isinstance(op.get("responses"), dict):
                            row["responses"] = op.get("responses")
                    ops.append(row)
        return ops

    def _extract_schemas(spec, openapi_version, lazy_loading):
        if not isinstance(spec, dict):
            return {}
        if openapi_version and openapi_version.startswith("3"):
            comps = spec.get("components")
            schemas = comps.get("schemas") if isinstance(comps, dict) else None
            if not isinstance(schemas, dict):
                return {}
            if not lazy_loading:
                return schemas
            # lazy: only include schema names with empty placeholder
            return {k: {} for k in schemas.keys() if isinstance(k, str)}
        if spec.get("swagger") == "2.0":
            defs = spec.get("definitions")
            if not isinstance(defs, dict):
                return {}
            if not lazy_loading:
                return defs
            return {k: {} for k in defs.keys() if isinstance(k, str)}
        return {}

    def _apply_filters(ops, filter_tag, path_prefix):
        out = ops
        if isinstance(filter_tag, str) and filter_tag.strip():
            ft = filter_tag.strip()
            out = [o for o in out if isinstance(o, dict) and ft in (o.get("tags") or [])]
        if isinstance(path_prefix, str) and path_prefix != "":
            pp = path_prefix
            out = [o for o in out if isinstance(o, dict) and isinstance(o.get("path"), str) and o.get("path").startswith(pp)]
        return out

    # --- validate inputs ---
    if not isinstance(url, str) or not url.strip():
        _log("error", error_code="VALIDATION_ERROR", message="url is required and must be a non-empty string")
        return _err("VALIDATION_ERROR", "url is required and must be a non-empty string")
    if not _is_headers_obj(headers):
        _log("error", error_code="VALIDATION_ERROR", message="headers must be an object of strings")
        return _err("VALIDATION_ERROR", "headers must be an object of strings")

    if includeSchemas is None:
        includeSchemas = False
    if includeDetails is None:
        includeDetails = False
    if skipValidation is None:
        skipValidation = False
    if useCache is None:
        useCache = False
    if lazyLoading is None:
        lazyLoading = False

    for nm, v in [("includeSchemas", includeSchemas), ("includeDetails", includeDetails), ("skipValidation", skipValidation), ("useCache", useCache), ("lazyLoading", lazyLoading)]:
        if not isinstance(v, bool):
            _log("error", error_code="VALIDATION_ERROR", message=f"{nm} must be boolean")
            return _err("VALIDATION_ERROR", f"{nm} must be boolean")

    if cacheTTLMinutes is not None:
        if not isinstance(cacheTTLMinutes, (int, float)) or isinstance(cacheTTLMinutes, bool):
            _log("error", error_code="VALIDATION_ERROR", message="cacheTTLMinutes must be a number")
            return _err("VALIDATION_ERROR", "cacheTTLMinutes must be a number")
        if cacheTTLMinutes < 0 or cacheTTLMinutes > 525600:
            _log("error", error_code="VALIDATION_ERROR", message="cacheTTLMinutes must be in [0, 525600]")
            return _err("VALIDATION_ERROR", "cacheTTLMinutes must be in [0, 525600]")

    if filterTag is not None and not isinstance(filterTag, str):
        _log("error", error_code="VALIDATION_ERROR", message="filterTag must be a string")
        return _err("VALIDATION_ERROR", "filterTag must be a string")
    if pathPrefix is not None and not isinstance(pathPrefix, str):
        _log("error", error_code="VALIDATION_ERROR", message="pathPrefix must be a string")
        return _err("VALIDATION_ERROR", "pathPrefix must be a string")

    url_norm = _normalize_url(url)
    if not url_norm:
        _log("error", error_code="VALIDATION_ERROR", message="url must be a valid http(s) URL")
        return _err("VALIDATION_ERROR", "url must be a valid http(s) URL")

    # --- load collections ---
    docs = _load("openapi_documents.json")
    parses = _load("openapi_parses.json")
    if not isinstance(docs, list): docs = []
    if not isinstance(parses, list): parses = []

    transitions_doc = {"fetching": ["active", "failed"], "active": ["stale", "deleted", "fetching"], "stale": ["fetching", "deleted"], "failed": ["fetching", "deleted"], "deleted": []}

    # --- upsert document by url_normalized ---
    doc = None
    for d in docs:
        if isinstance(d, dict) and d.get("url_normalized") == url_norm and d.get("status") != "deleted":
            doc = d
            break

    if doc is None:
        doc = {
            "id": _gen_id("doc"),
            "url": url,
            "url_normalized": url_norm,
            "last_request_headers": headers if headers is not None else None,
            "etag": None,
            "last_modified": None,
            "content_type": None,
            "http_status": None,
            "fetch_error": None,
            "raw_bytes": None,
            "raw_body": None,
            "content_sha256": None,
            "openapi_version": None,
            "title": None,
            "version": None,
            "status": "fetching",
            "cache_expires_at": None,
            "last_fetched_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        docs.append(doc)
        _save("openapi_documents.json", docs)
    else:
        doc["url"] = url
        if headers is not None:
            doc["last_request_headers"] = headers
        doc["updated_at"] = now_iso
        _save("openapi_documents.json", docs)

    # If cacheTTLMinutes provided, set cache_expires_at = now + ttl
    if cacheTTLMinutes is not None:
        expires = now + datetime.timedelta(minutes=float(cacheTTLMinutes))
        # constraint: cache_expires_at >= created_at
        doc_created = doc.get("created_at")
        doc["cache_expires_at"] = expires.replace(microsecond=0).isoformat() + "Z"
        doc["updated_at"] = now_iso
        _save("openapi_documents.json", docs)

    def _dt_from_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # --- decide fetch vs cache reuse ---
    reused_cache = False
    body_text = None
    http_status = None
    content_type = None
    etag = None
    last_modified = None

    if useCache:
        exp = _dt_from_iso(doc.get("cache_expires_at"))
        if exp is not None and exp > now and isinstance(doc.get("raw_body"), str) and doc.get("raw_body") != "":
            body_text = doc.get("raw_body")
            reused_cache = True
            http_status = doc.get("http_status") or 200
            content_type = doc.get("content_type")
            etag = doc.get("etag")
            last_modified = doc.get("last_modified")

    if body_text is None:
        # transition to fetching
        cur = doc.get("status") or "active"
        if cur != "fetching":
            if not _allowed_transition(cur, "fetching", transitions_doc):
                _log("error", url_norm, doc.get("id"), error_code="INVALID_TRANSITION", message=f"Cannot transition document from {cur} to fetching")
                return _err("INVALID_TRANSITION", f"Cannot transition document from {cur} to fetching")
            doc["status"] = "fetching"
            doc["updated_at"] = now_iso
            _save("openapi_documents.json", docs)

        # fetch
        req_headers = {}
        if isinstance(headers, dict):
            req_headers.update(headers)

        if isinstance(doc.get("etag"), str) and doc.get("etag"):
            req_headers.setdefault("If-None-Match", doc.get("etag"))
        if isinstance(doc.get("last_modified"), str) and doc.get("last_modified"):
            req_headers.setdefault("If-Modified-Since", doc.get("last_modified"))

        fetch_error = None
        try:
            req = urllib.request.Request(url_norm, headers=req_headers, method="GET")
            with urllib.request.urlopen(req, timeout=20) as resp:
                http_status = getattr(resp, "status", None)
                content_type = resp.headers.get("Content-Type")
                etag = resp.headers.get("ETag")
                last_modified = resp.headers.get("Last-Modified")
                raw = resp.read()
                try:
                    body_text = raw.decode("utf-8")
                except UnicodeDecodeError:
                    body_text = raw.decode("latin1")
        except urllib.error.HTTPError as e:
            http_status = int(getattr(e, "code", 0) or 0) or None
            content_type = e.headers.get("Content-Type") if getattr(e, "headers", None) else None
            etag = e.headers.get("ETag") if getattr(e, "headers", None) else None
            last_modified = e.headers.get("Last-Modified") if getattr(e, "headers", None) else None
            if http_status == 304 and isinstance(doc.get("raw_body"), str) and doc.get("raw_body") != "":
                body_text = doc.get("raw_body")
                reused_cache = True
            else:
                fetch_error = f"HTTPError {http_status}"
        except urllib.error.URLError as e:
            fetch_error = str(e.reason) if getattr(e, "reason", None) else str(e)
        except Exception as e:
            fetch_error = str(e)

        if body_text is None:
            doc["status"] = "failed"
            doc["http_status"] = http_status
            doc["content_type"] = content_type
            doc["etag"] = etag if etag else doc.get("etag")
            doc["last_modified"] = last_modified if last_modified else doc.get("last_modified")
            doc["fetch_error"] = fetch_error or "Failed to fetch document"
            doc["updated_at"] = now_iso
            _save("openapi_documents.json", docs)
            _log("error", url_norm, doc.get("id"), http_status=http_status, error_code="NOT_FOUND", message=doc["fetch_error"])
            return _err("NOT_FOUND", f"Document could not be retrieved from URL: {url_norm}", http_status=http_status, fetch_error=doc["fetch_error"])

    # parse spec
    sha = hashlib.sha256(body_text.encode("utf-8")).hexdigest()
    raw_bytes = len(body_text.encode("utf-8"))
    try:
        spec = _parse_spec(body_text)
    except Exception as e:
        doc["status"] = "failed"
        doc["http_status"] = http_status if http_status is not None else (doc.get("http_status") or 200)
        doc["content_type"] = content_type if content_type is not None else doc.get("content_type")
        doc["fetch_error"] = f"Parse error: {str(e)}"
        doc["raw_body"] = body_text
        doc["raw_bytes"] = raw_bytes
        doc["content_sha256"] = sha
        doc["updated_at"] = now_iso
        _save("openapi_documents.json", docs)
        _log("error", url_norm, doc.get("id"), http_status=doc.get("http_status"), error_code="VALIDATION_ERROR", message=doc["fetch_error"])
        return _err("VALIDATION_ERROR", "PARSE_ERROR: Unable to parse Swagger/OpenAPI document", details=doc["fetch_error"])

    openapi_version, title, ver = _detect_info(spec)

    # update doc to active with fetched content if we fetched (or 304/cached)
    if doc.get("status") != "active":
        cur = doc.get("status") or "fetching"
        if cur != "active" and not _allowed_transition(cur, "active", transitions_doc):
            doc["status"] = "active"
        else:
            doc["status"] = "active"
    doc["http_status"] = http_status if http_status is not None else (doc.get("http_status") or 200)
    doc["content_type"] = content_type if content_type is not None else doc.get("content_type")
    doc["etag"] = etag if etag else doc.get("etag")
    doc["last_modified"] = last_modified if last_modified else doc.get("last_modified")
    doc["fetch_error"] = None
    doc["raw_body"] = body_text
    doc["raw_bytes"] = raw_bytes
    doc["content_sha256"] = sha
    doc["openapi_version"] = openapi_version
    doc["title"] = title
    doc["version"] = ver
    doc["last_fetched_at"] = now_iso if not reused_cache else (doc.get("last_fetched_at") or now_iso)
    doc["updated_at"] = now_iso
    _save("openapi_documents.json", docs)

    # build operations + filters
    ops = _build_operations_index(spec, includeDetails)
    if not includeDetails:
        for o in ops:
            for k in ("parameters", "requestBody", "responses"):
                if k in o:
                    del o[k]
    ops_filtered = _apply_filters(ops, filterTag, pathPrefix)

    # schemas
    schemas_blob = None
    schema_count = 0
    if includeSchemas:
        schemas_blob = _extract_schemas(spec, openapi_version, lazyLoading)
        if not isinstance(schemas_blob, dict):
            schemas_blob = {}
        schema_count = len(schemas_blob)
    else:
        schemas_blob = None
        schema_count = 0

    # validation errors (minimal; only when skipValidation=False)
    validation_errors = None
    if not skipValidation:
        errs = []
        if openapi_version is None:
            errs.append({"message": "Could not detect OpenAPI/Swagger version"})
        if not isinstance(spec, dict) or ("paths" not in spec):
            errs.append({"message": "Spec missing 'paths' object"})
        validation_errors = errs if errs else None

    parse_options = {
        "mode": "optimized",
        "includeSchemas": includeSchemas,
        "includeDetails": includeDetails,
        "skipValidation": skipValidation,
        "useCache": useCache,
        "cacheTTLMinutes": cacheTTLMinutes,
        "lazyLoading": lazyLoading,
        "filterTag": filterTag,
        "pathPrefix": pathPrefix,
    }
    fp_src = doc.get("content_sha256", "") + "|" + json.dumps(parse_options, sort_keys=True, separators=(",", ":"))
    parse_fingerprint = hashlib.sha256(fp_src.encode("utf-8")).hexdigest()

    existing = None
    for p in parses:
        if isinstance(p, dict) and p.get("parse_fingerprint") == parse_fingerprint:
            existing = p
            break

    if existing is None:
        parse_id = _gen_id("parse")
        parse_row = {
            "id": parse_id,
            "document_id": doc["id"],
            "mode": "optimized",
            "include_schemas": bool(includeSchemas),
            "include_details": bool(includeDetails),
            "skip_validation": bool(skipValidation),
            "use_cache": bool(useCache),
            "cache_ttl_minutes": float(cacheTTLMinutes) if cacheTTLMinutes is not None else None,
            "lazy_loading": bool(lazyLoading),
            "filter_tag": filterTag if isinstance(filterTag, str) else None,
            "path_prefix": pathPrefix if isinstance(pathPrefix, str) else None,
            "parse_fingerprint": parse_fingerprint,
            "operation_count": int(len(ops_filtered)),
            "schema_count": int(schema_count),
            "operations_index": ops_filtered,
            "schemas_blob": schemas_blob,
            "validation_errors": validation_errors,
            "status": "succeeded",
            "error_message": None,
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        parses.append(parse_row)
        _save("openapi_parses.json", parses)
    else:
        parse_id = existing.get("id")
        parse_row = existing

    _log("ok", url_norm, doc.get("id"), parse_id=parse_id, http_status=doc.get("http_status"), message="succeeded")
    return {
        "document": {
            "id": doc.get("id"),
            "url": doc.get("url"),
            "urlNormalized": doc.get("url_normalized"),
            "status": doc.get("status"),
            "httpStatus": doc.get("http_status"),
            "contentType": doc.get("content_type"),
            "openapiVersion": doc.get("openapi_version"),
            "title": doc.get("title"),
            "version": doc.get("version"),
            "lastFetchedAt": doc.get("last_fetched_at"),
            "cacheExpiresAt": doc.get("cache_expires_at"),
        },
        "parse": {
            "id": parse_row.get("id"),
            "mode": parse_row.get("mode"),
            "operationCount": parse_row.get("operation_count"),
            "schemaCount": parse_row.get("schema_count"),
            "operations": parse_row.get("operations_index"),
            "schemas": parse_row.get("schemas_blob"),
            "validationErrors": parse_row.get("validation_errors"),
            "status": parse_row.get("status"),
            "errorMessage": parse_row.get("error_message"),
        },
        "meta": {
            "cachedDocument": bool(reused_cache),
            "cachedParse": existing is not None,
            "latencyMs": int((time.time() - t0) * 1000),
        }
    }

def parse_swagger_lite(url, headers=None, includeSchemas=None, includeDetails=None, skipValidation=None, useCache=None, cacheTTLMinutes=None, lazyLoading=None, filterTag=None, pathPrefix=None, **_extra):
    import json, os, datetime, hashlib, urllib.request, urllib.error, urllib.parse, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _dt_parse(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _url_normalize(u):
        u = u.strip()
        p = urllib.parse.urlsplit(u)
        scheme = (p.scheme or "").lower()
        if scheme not in ("http", "https"):
            return None
        netloc = (p.netloc or "").strip().lower()
        if not netloc:
            return None
        path = p.path or "/"
        path = re.sub(r"/{2,}", "/", path)
        host, sep, port = netloc.partition(":")
        if sep:
            if (scheme == "http" and port == "80") or (scheme == "https" and port == "443"):
                netloc = host
        q = p.query or ""
        if path != "/" and path.endswith("/"):
            path = path[:-1]
        return urllib.parse.urlunsplit((scheme, netloc, path, q, ""))

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + now_iso + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    def _record_doc_status_transition(doc, new_status):
        transitions = {
            "fetching": {"active", "failed"},
            "active": {"stale", "deleted", "fetching"},
            "stale": {"fetching", "deleted"},
            "failed": {"fetching", "deleted"},
            "deleted": set(),
        }
        cur = doc.get("status")
        if cur is None:
            return False, "missing current status"
        if cur == new_status:
            return True, None
        allowed = transitions.get(cur, set())
        if new_status not in allowed:
            return False, f"Illegal status transition {cur} -> {new_status}"
        doc["status"] = new_status
        doc["updated_at"] = now_iso
        return True, None

    def _parse_spec_minimal(raw_text, include_details, include_schemas, lazy_loading):
        # JSON first, minimal YAML fallback identical to parse-swagger
        validation_errors = []
        spec = None
        content_type = None

        try:
            spec = json.loads(raw_text)
            content_type = "application/json"
        except Exception:
            def _yaml_parse_minimal(text):
                lines = text.splitlines()
                if lines and lines[0].startswith("\ufeff"):
                    lines[0] = lines[0].lstrip("\ufeff")
                root = {}
                stack = [(-1, root, None)]
                for raw_line in lines:
                    if not raw_line.strip() or raw_line.lstrip().startswith("#"):
                        continue
                    indent = len(raw_line) - len(raw_line.lstrip(" "))
                    line = raw_line.strip()
                    if line.startswith("- "):
                        item = line[2:].strip()
                        while stack and indent <= stack[-1][0]:
                            stack.pop()
                        if not stack:
                            raise ValueError("Bad YAML indentation")
                        parent = stack[-1][1]
                        if not isinstance(parent, list):
                            last_key = stack[-1][2]
                            if last_key is None or not isinstance(parent, dict):
                                raise ValueError("Bad YAML list placement")
                            if last_key not in parent or not isinstance(parent[last_key], list):
                                parent[last_key] = []
                            parent = parent[last_key]
                            stack[-1] = (stack[-1][0], parent, None)
                        def _scalar(v):
                            if v in ("true", "false"):
                                return v == "true"
                            if v == "null":
                                return None
                            try:
                                if "." in v:
                                    return float(v)
                                return int(v)
                            except Exception:
                                pass
                            if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                                return v[1:-1]
                            return v
                        parent.append(_scalar(item))
                        continue
                    if ":" in line:
                        k, v = line.split(":", 1)
                        k = k.strip()
                        v = v.strip()
                        while stack and indent <= stack[-1][0]:
                            stack.pop()
                        if not stack:
                            raise ValueError("Bad YAML indentation")
                        container = stack[-1][1]
                        if not isinstance(container, dict):
                            raise ValueError("Bad YAML mapping placement")
                        if v == "":
                            container[k] = {}
                            stack.append((indent, container[k], k))
                        else:
                            def _scalar(vv):
                                if vv in ("true", "false"):
                                    return vv == "true"
                                if vv == "null":
                                    return None
                                try:
                                    if "." in vv:
                                        return float(vv)
                                    return int(vv)
                                except Exception:
                                    pass
                                if (vv.startswith('"') and vv.endswith('"')) or (vv.startswith("'") and vv.endswith("'")):
                                    return vv[1:-1]
                                return vv
                            container[k] = _scalar(v)
                            stack.append((indent, container, k))
                        continue
                    raise ValueError("Unsupported YAML syntax")
                return root
            try:
                spec = _yaml_parse_minimal(raw_text)
                content_type = "application/yaml"
            except Exception as e:
                raise ValueError(f"Unable to parse document as JSON or YAML: {str(e)}")

        openapi_version = None
        title = None
        ver = None
        if isinstance(spec, dict):
            if "openapi" in spec and isinstance(spec.get("openapi"), str):
                openapi_version = spec.get("openapi")
            elif "swagger" in spec and isinstance(spec.get("swagger"), str):
                openapi_version = spec.get("swagger")
            info = spec.get("info")
            if isinstance(info, dict):
                title = info.get("title") if isinstance(info.get("title"), str) else None
                ver = info.get("version") if isinstance(info.get("version"), str) else None
        if not openapi_version:
            validation_errors.append({"message": "Unable to detect OpenAPI/Swagger version (missing 'openapi' or 'swagger' field)."})
            openapi_version = None

        operations = []
        paths = spec.get("paths") if isinstance(spec, dict) else None
        if isinstance(paths, dict):
            for path, methods in paths.items():
                if not isinstance(path, str) or not isinstance(methods, dict):
                    continue
                for method, op in methods.items():
                    if not isinstance(method, str):
                        continue
                    m = method.lower()
                    if m not in ("get", "put", "post", "delete", "patch", "head", "options", "trace"):
                        continue
                    if not isinstance(op, dict):
                        op = {}
                    entry = {
                        "method": m.upper(),
                        "path": path,
                        "operationId": op.get("operationId") if isinstance(op.get("operationId"), str) else None,
                        "summary": op.get("summary") if isinstance(op.get("summary"), str) else None,
                        "tags": op.get("tags") if isinstance(op.get("tags"), list) else None,
                    }
                    if include_details:
                        if "parameters" in op:
                            entry["parameters"] = op.get("parameters")
                        if "requestBody" in op:
                            entry["requestBody"] = op.get("requestBody")
                        if "responses" in op:
                            entry["responses"] = op.get("responses")
                    operations.append(entry)

        operations_index = {"operations": operations, "mode": "lite"}

        schemas_blob = None
        schema_count = 0
        if include_schemas:
            schemas = None
            if isinstance(spec, dict):
                comps = spec.get("components")
                if isinstance(comps, dict) and isinstance(comps.get("schemas"), dict):
                    schemas = comps.get("schemas")
                elif isinstance(spec.get("definitions"), dict):
                    schemas = spec.get("definitions")
            if isinstance(schemas, dict):
                if lazy_loading:
                    # store minimal placeholder keys only
                    schemas_blob = {k: {"$ref": f"#/schemas/{k}"} for k in schemas.keys()}
                else:
                    schemas_blob = schemas
                schema_count = len(schemas.keys())
            else:
                schemas_blob = {} if not lazy_loading else {}
                schema_count = 0

        return openapi_version, title, ver, operations_index, schemas_blob, schema_count, validation_errors, content_type

    def _apply_filters(operations_index, filter_tag=None, path_prefix=None):
        ops = operations_index.get("operations") if isinstance(operations_index, dict) else None
        if not isinstance(ops, list):
            return {"operations": [], "mode": operations_index.get("mode") if isinstance(operations_index, dict) else None}
        out = []
        for op in ops:
            if not isinstance(op, dict):
                continue
            if path_prefix is not None:
                p = op.get("path")
                if not (isinstance(p, str) and p.startswith(path_prefix)):
                    continue
            if filter_tag is not None:
                tags = op.get("tags")
                ok = False
                if isinstance(tags, list):
                    for t in tags:
                        if t == filter_tag:
                            ok = True
                            break
                if not ok:
                    continue
            out.append(op)
        new_idx = dict(operations_index)
        new_idx["operations"] = out
        return new_idx

    # Validate inputs
    if not isinstance(url, str) or not url.strip():
        return _err("VALIDATION_ERROR", "url must be a non-empty string")
    if headers is not None:
        if not isinstance(headers, dict):
            return _err("VALIDATION_ERROR", "headers must be an object of string values")
        for k, v in headers.items():
            if not isinstance(k, str) or not isinstance(v, str):
                return _err("VALIDATION_ERROR", "headers must be an object of string values")

    if includeSchemas is None:
        includeSchemas = False
    if includeDetails is None:
        includeDetails = False
    if skipValidation is None:
        skipValidation = False
    if useCache is None:
        useCache = False
    if lazyLoading is None:
        lazyLoading = False

    for name, val in [("includeSchemas", includeSchemas), ("includeDetails", includeDetails), ("skipValidation", skipValidation), ("useCache", useCache), ("lazyLoading", lazyLoading)]:
        if not isinstance(val, bool):
            return _err("VALIDATION_ERROR", f"{name} must be a boolean")

    if filterTag is not None and not isinstance(filterTag, str):
        return _err("VALIDATION_ERROR", "filterTag must be a string")
    if pathPrefix is not None and not isinstance(pathPrefix, str):
        return _err("VALIDATION_ERROR", "pathPrefix must be a string")

    if cacheTTLMinutes is not None:
        if not isinstance(cacheTTLMinutes, (int, float)) or isinstance(cacheTTLMinutes, bool):
            return _err("VALIDATION_ERROR", "cacheTTLMinutes must be a number")
        if cacheTTLMinutes < 0 or cacheTTLMinutes > 525600:
            return _err("VALIDATION_ERROR", "cacheTTLMinutes must be in [0, 525600]")

    url_norm = _url_normalize(url)
    if url_norm is None:
        return _err("VALIDATION_ERROR", "url must be a valid http(s) URL")

    docs = _load("openapi_documents.json")
    parses = _load("openapi_parses.json")

    # Upsert openapi_documents by url_normalized
    doc = None
    for d in docs:
        if isinstance(d, dict) and d.get("url_normalized") == url_norm:
            doc = d
            break

    if doc is None:
        doc = {
            "id": _new_id("doc"),
            "url": url,
            "url_normalized": url_norm,
            "last_request_headers": headers,
            "etag": None,
            "last_modified": None,
            "content_type": None,
            "http_status": None,
            "fetch_error": None,
            "raw_bytes": None,
            "raw_body": None,
            "content_sha256": None,
            "openapi_version": None,
            "title": None,
            "version": None,
            "status": "active",  # will set to fetching only if we need to fetch
            "cache_expires_at": None,
            "last_fetched_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        docs.append(doc)
    else:
        doc["url"] = url
        doc["last_request_headers"] = headers
        doc["updated_at"] = now_iso

    # cache TTL set/update for this run (persist on document)
    if cacheTTLMinutes is not None:
        expires = now + datetime.timedelta(minutes=float(cacheTTLMinutes))
        # constraint: cache_expires_at >= created_at
        created_dt = _dt_parse(doc.get("created_at")) or now
        if expires < created_dt:
            return _err("VALIDATION_ERROR", "cache_expires_at must be >= created_at")
        doc["cache_expires_at"] = expires.replace(microsecond=0).isoformat() + "Z"

    # Decide whether to use cached content
    cached_ok = False
    if useCache:
        exp = _dt_parse(doc.get("cache_expires_at"))
        if exp is not None and exp > now and isinstance(doc.get("raw_body"), str) and doc.get("raw_body"):
            cached_ok = True

    raw_text = None
    http_status = None
    fetch_error = None
    content_type = None
    etag = None
    last_modified = None

    if cached_ok:
        raw_text = doc.get("raw_body")
        http_status = doc.get("http_status")
        content_type = doc.get("content_type")
        etag = doc.get("etag")
        last_modified = doc.get("last_modified")
    else:
        # Need to fetch
        ok, msg = _record_doc_status_transition(doc, "fetching")
        if not ok:
            return _err("INVALID_TRANSITION", msg)

        req = urllib.request.Request(url, method="GET")
        if isinstance(headers, dict):
            for k, v in headers.items():
                req.add_header(k, v)
        try:
            with urllib.request.urlopen(req, timeout=25) as resp:
                http_status = getattr(resp, "status", None) or 200
                resp_headers = dict(resp.headers.items()) if resp.headers else {}
                content_type = resp_headers.get("Content-Type")
                etag = resp_headers.get("ETag")
                last_modified = resp_headers.get("Last-Modified")
                data = resp.read()
                charset = None
                if isinstance(content_type, str) and "charset=" in content_type.lower():
                    try:
                        charset = content_type.split("charset=", 1)[1].split(";", 1)[0].strip()
                    except Exception:
                        charset = None
                if not charset:
                    charset = "utf-8"
                try:
                    raw_text = data.decode(charset, errors="replace")
                except Exception:
                    raw_text = data.decode("utf-8", errors="replace")
        except urllib.error.HTTPError as e:
            http_status = getattr(e, "code", None)
            fetch_error = f"HTTPError: {str(e)}"
        except urllib.error.URLError as e:
            fetch_error = f"URLError: {str(e)}"
        except Exception as e:
            fetch_error = f"FetchError: {str(e)}"

        if raw_text is None:
            doc["http_status"] = http_status
            doc["fetch_error"] = fetch_error
            doc["content_type"] = content_type
            doc["etag"] = etag
            doc["last_modified"] = last_modified
            ok, msg = _record_doc_status_transition(doc, "failed")
            if not ok:
                return _err("INVALID_TRANSITION", msg)
            _save("openapi_documents.json", docs)
            return _err("NOT_FOUND", "Document could not be retrieved from the given URL", http_status=http_status, fetch_error=fetch_error)

        sha = hashlib.sha256(raw_text.encode("utf-8", errors="replace")).hexdigest()
        doc["raw_body"] = raw_text
        doc["raw_bytes"] = len(raw_text.encode("utf-8", errors="replace"))
        doc["content_sha256"] = sha
        doc["content_type"] = content_type
        doc["http_status"] = http_status
        doc["fetch_error"] = None
        doc["etag"] = etag
        doc["last_modified"] = last_modified
        doc["last_fetched_at"] = now_iso
        ok, msg = _record_doc_status_transition(doc, "active")
        if not ok:
            return _err("INVALID_TRANSITION", msg)

    # Parse
    parse_started = now_iso
    try:
        openapi_version, title, ver, operations_index, schemas_blob, schema_count, validation_errors, detected_ct = _parse_spec_minimal(
            raw_text=raw_text,
            include_details=includeDetails,
            include_schemas=includeSchemas,
            lazy_loading=lazyLoading,
        )
        # Optionally "validate"
        if not skipValidation and validation_errors:
            # keep going; store errors
            pass
    except Exception as e:
        parse_finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        parse_fingerprint = hashlib.sha256(
            (str(doc.get("content_sha256") or "") + "|lite|" + str(includeSchemas) + "|" + str(includeDetails) + "|" + str(skipValidation) + "|" + str(useCache) + "|" + str(cacheTTLMinutes) + "|" + str(lazyLoading) + "|" + str(filterTag) + "|" + str(pathPrefix)).encode("utf-8")
        ).hexdigest()
        existing = None
        for pr in parses:
            if isinstance(pr, dict) and pr.get("parse_fingerprint") == parse_fingerprint:
                existing = pr
                break
        if existing is None:
            pr = {
                "id": _new_id("parse"),
                "document_id": doc["id"],
                "mode": "lite",
                "include_schemas": bool(includeSchemas),
                "include_details": bool(includeDetails),
                "skip_validation": bool(skipValidation),
                "use_cache": bool(useCache),
                "cache_ttl_minutes": (float(cacheTTLMinutes) if cacheTTLMinutes is not None else None),
                "lazy_loading": bool(lazyLoading),
                "filter_tag": filterTag,
                "path_prefix": pathPrefix,
                "parse_fingerprint": parse_fingerprint,
                "operation_count": 0,
                "schema_count": 0,
                "operations_index": {"operations": [], "mode": "lite"},
                "schemas_blob": None,
                "validation_errors": None,
                "status": "failed",
                "error_message": f"PARSE_ERROR: {str(e)}",
                "started_at": parse_started,
                "finished_at": parse_finished,
                "created_at": now_iso,
                "updated_at": parse_finished,
            }
            parses.append(pr)
            existing = pr
            _save("openapi_parses.json", parses)
        _save("openapi_documents.json", docs)
        return _err("VALIDATION_ERROR", "PARSE_ERROR: unable to parse the document", detail=str(e))

    # Apply filters
    operations_index_filtered = _apply_filters(operations_index, filter_tag=filterTag, path_prefix=pathPrefix)
    operation_count = len(operations_index_filtered.get("operations", [])) if isinstance(operations_index_filtered, dict) else 0

    # Enforce includeDetails=false: ensure no bodies (already controlled); extra safety strip keys
    if not includeDetails and isinstance(operations_index_filtered, dict):
        for op in operations_index_filtered.get("operations", []) or []:
            if isinstance(op, dict):
                for k in ("requestBody", "responses", "parameters", "consumes", "produces"):
                    if k in op:
                        del op[k]

    # Enforce includeSchemas=false
    if not includeSchemas:
        schemas_blob = None
        schema_count = 0

    # Update doc extracted fields
    doc["openapi_version"] = openapi_version
    doc["title"] = title
    doc["version"] = ver
    if doc.get("content_type") is None and detected_ct:
        doc["content_type"] = detected_ct
    doc["updated_at"] = now_iso

    parse_fingerprint = hashlib.sha256(
        (str(doc.get("content_sha256") or "") + "|lite|" + str(includeSchemas) + "|" + str(includeDetails) + "|" + str(skipValidation) + "|" + str(useCache) + "|" + str(cacheTTLMinutes) + "|" + str(lazyLoading) + "|" + str(filterTag) + "|" + str(pathPrefix)).encode("utf-8")
    ).hexdigest()

    # unique(parse_fingerprint) reuse if exists
    existing = None
    for pr in parses:
        if isinstance(pr, dict) and pr.get("parse_fingerprint") == parse_fingerprint:
            existing = pr
            break

    parse_finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    if existing is None:
        pr = {
            "id": _new_id("parse"),
            "document_id": doc["id"],
            "mode": "lite",
            "include_schemas": bool(includeSchemas),
            "include_details": bool(includeDetails),
            "skip_validation": bool(skipValidation),
            "use_cache": bool(useCache),
            "cache_ttl_minutes": (float(cacheTTLMinutes) if cacheTTLMinutes is not None else None),
            "lazy_loading": bool(lazyLoading),
            "filter_tag": filterTag,
            "path_prefix": pathPrefix,
            "parse_fingerprint": parse_fingerprint,
            "operation_count": int(operation_count),
            "schema_count": int(schema_count),
            "operations_index": operations_index_filtered,
            "schemas_blob": schemas_blob,
            "validation_errors": (validation_errors if (not skipValidation and validation_errors) else None),
            "status": "succeeded",
            "error_message": None,
            "started_at": parse_started,
            "finished_at": parse_finished,
            "created_at": now_iso,
            "updated_at": parse_finished,
        }
        parses.append(pr)
        existing = pr
        _save("openapi_parses.json", parses)

    _save("openapi_documents.json", docs)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "document": {
            "id": doc["id"],
            "url": doc["url"],
            "url_normalized": doc["url_normalized"],
            "status": doc["status"],
            "http_status": doc.get("http_status"),
            "content_type": doc.get("content_type"),
            "etag": doc.get("etag"),
            "last_modified": doc.get("last_modified"),
            "raw_bytes": doc.get("raw_bytes"),
            "content_sha256": doc.get("content_sha256"),
            "openapi_version": doc.get("openapi_version"),
            "title": doc.get("title"),
            "version": doc.get("version"),
            "last_fetched_at": doc.get("last_fetched_at"),
            "cache_expires_at": doc.get("cache_expires_at"),
            "updated_at": doc.get("updated_at"),
            "created_at": doc.get("created_at"),
            "used_cache": bool(cached_ok),
        },
        "parse": {
            "id": existing["id"],
            "document_id": existing["document_id"],
            "mode": existing["mode"],
            "includeSchemas": existing["include_schemas"],
            "includeDetails": existing["include_details"],
            "skipValidation": existing["skip_validation"],
            "useCache": existing["use_cache"],
            "cacheTTLMinutes": existing.get("cache_ttl_minutes"),
            "lazyLoading": existing["lazy_loading"],
            "filterTag": existing.get("filter_tag"),
            "pathPrefix": existing.get("path_prefix"),
            "operationCount": existing["operation_count"],
            "schemaCount": existing["schema_count"],
            "operationsIndex": existing["operations_index"],
            "schemas": existing["schemas_blob"] if includeSchemas else None,
            "validationErrors": existing.get("validation_errors"),
            "status": existing["status"],
            "started_at": existing.get("started_at"),
            "finished_at": existing.get("finished_at"),
        },
        "meta": {"latency_ms": latency_ms},
    }

def generate_typescript_types(swaggerUrl=None, outputDir=None, overwrite=None, filePrefix=None, fileSuffix=None, useNamespace=None, namespace=None, generateEnums=None, strictTypes=None, excludeSchemas=None, includeSchemas=None, generateIndex=None, headers=None, useCache=None, cacheTTLMinutes=None, skipValidation=None, lazyLoading=None, **_extra):
    import json, os, datetime, hashlib, time, urllib.parse, urllib.request, urllib.error, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "generate-typescript-types"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(status, error_code=None, job_id=None, document_id=None):
        # Append to first existing log collection if present.
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                rid = f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{int((time.time()%1)*1e6)}"
                logs.append({
                    "id": rid,
                    "endpoint": endpoint,
                    "credential": None,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": _iso_now(),
                    "job_id": job_id,
                    "document_id": document_id,
                })
                _save(fname, logs)
                break

    def _is_bool(x): return isinstance(x, bool)
    def _is_num(x): return isinstance(x, (int, float)) and not isinstance(x, bool)

    def _norm_url(u):
        u = u.strip()
        p = urllib.parse.urlsplit(u)
        scheme = (p.scheme or "").lower()
        netloc = (p.netloc or "").lower()
        path = p.path or ""
        if ":" in netloc:
            host, port = netloc.rsplit(":", 1)
            if (scheme == "http" and port == "80") or (scheme == "https" and port == "443"):
                netloc = host
        path = re.sub(r"/{2,}", "/", path)
        query = p.query or ""
        if query:
            q = urllib.parse.parse_qsl(query, keep_blank_values=True)
            q.sort()
            query = urllib.parse.urlencode(q)
        return urllib.parse.urlunsplit((scheme, netloc, path, query, ""))

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            # allow naive or offset-aware
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _utcnow_dt():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _gen_id(prefix):
        # ULID-like enough for uniqueness; keep vendor-ish prefixes
        rand = hashlib.sha256(os.urandom(16)).hexdigest()[:16]
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}{rand}"

    def _sha256_text(s):
        h = hashlib.sha256()
        h.update(s.encode("utf-8", errors="replace"))
        return h.hexdigest()

    def _extract_spec_meta(raw_text):
        # Best-effort JSON parse; if YAML, keep unknowns.
        title = None
        ver = None
        oav = None
        obj = None
        try:
            obj = json.loads(raw_text)
        except Exception:
            obj = None
        if isinstance(obj, dict):
            if "openapi" in obj and isinstance(obj.get("openapi"), str):
                oav = obj.get("openapi")
            elif "swagger" in obj and isinstance(obj.get("swagger"), str):
                oav = obj.get("swagger")
            info = obj.get("info")
            if isinstance(info, dict):
                if isinstance(info.get("title"), str):
                    title = info.get("title")
                if isinstance(info.get("version"), str):
                    ver = info.get("version")
        return obj, oav, title, ver

    def _gen_ts_types_from_spec(spec_obj, opts):
        # Minimal deterministic generation: derive interface/type names from schemas; fall back to empty.
        # This is not a full generator; but it must have real effect and respect options.
        lines = []
        header = [
            "/* Generated by Swagger MCP Server (offline generator) */",
            "/* tool: generate-typescript-types */",
        ]
        lines.extend(header)
        if opts.get("strictTypes"):
            lines.append("/* strictTypes enabled */")
        lines.append("")

        ns = opts.get("namespace") if opts.get("useNamespace") else None
        if ns:
            lines.append(f"export namespace {ns} {{")

        indent = "  " if ns else ""

        def emit(line=""):
            lines.append(indent + line if line and indent else line)

        schemas = {}
        if isinstance(spec_obj, dict):
            comps = spec_obj.get("components")
            if isinstance(comps, dict):
                sch = comps.get("schemas")
                if isinstance(sch, dict):
                    schemas = sch
            # Swagger 2.0
            if not schemas and isinstance(spec_obj.get("definitions"), dict):
                schemas = spec_obj.get("definitions")

        include = opts.get("includeSchemas")
        exclude = opts.get("excludeSchemas")
        if include is not None:
            wanted = set(include)
            schemas = {k: v for k, v in schemas.items() if k in wanted}
        if exclude:
            banned = set(exclude)
            schemas = {k: v for k, v in schemas.items() if k not in banned}

        if not schemas:
            emit("export type ApiTypes = Record<string, unknown>;")
        else:
            emit("/* Schemas */")
            for name in sorted(schemas.keys()):
                safe = re.sub(r"[^A-Za-z0-9_]", "_", name)
                # very simple representation
                emit(f"export type {safe} = any;")

        if opts.get("generateEnums") and schemas:
            emit("")
            emit("/* Enums (best-effort placeholders) */")
            # no reliable enum extraction without deep parsing; emit placeholder union per schema that has enum
            for name in sorted(schemas.keys()):
                schema = schemas.get(name)
                if isinstance(schema, dict) and isinstance(schema.get("enum"), list) and schema["enum"]:
                    safe = re.sub(r"[^A-Za-z0-9_]", "_", name)
                    vals = []
                    for v in schema["enum"]:
                        if isinstance(v, str):
                            vals.append(json.dumps(v))
                        elif isinstance(v, (int, float)) and not isinstance(v, bool):
                            vals.append(str(v))
                        elif isinstance(v, bool):
                            vals.append("true" if v else "false")
                    if vals:
                        emit(f"export type {safe}Enum = " + " | ".join(vals) + ";")

        if ns:
            lines.append("}")

        return "\n".join(lines) + "\n", list(sorted(schemas.keys()))

    def _validate_array_of_strings(x, field):
        if x is None:
            return None
        if not isinstance(x, list):
            return _err("VALIDATION_ERROR", f"Parameter '{field}' must be an array of strings.", field=field)
        for i, v in enumerate(x):
            if not isinstance(v, str):
                return _err("VALIDATION_ERROR", f"Parameter '{field}' must be an array of strings.", field=field, index=i)
        return None

    # ---- Validate inputs (do not raise on missing) ----
    if swaggerUrl is None or not isinstance(swaggerUrl, str) or not swaggerUrl.strip():
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'swaggerUrl' must be a non-empty string.", field="swaggerUrl")

    if outputDir is not None and (not isinstance(outputDir, str) or not outputDir.strip()):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'outputDir' must be a non-empty string when provided.", field="outputDir")

    for bf, val in (
        ("overwrite", overwrite),
        ("useNamespace", useNamespace),
        ("generateEnums", generateEnums),
        ("strictTypes", strictTypes),
        ("generateIndex", generateIndex),
        ("useCache", useCache),
        ("skipValidation", skipValidation),
        ("lazyLoading", lazyLoading),
    ):
        if val is not None and not _is_bool(val):
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Parameter '{bf}' must be a boolean when provided.", field=bf)

    if filePrefix is not None and not isinstance(filePrefix, str):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'filePrefix' must be a string when provided.", field="filePrefix")
    if fileSuffix is not None and not isinstance(fileSuffix, str):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'fileSuffix' must be a string when provided.", field="fileSuffix")

    if namespace is not None and not isinstance(namespace, str):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'namespace' must be a string when provided.", field="namespace")
    if useNamespace is True and (namespace is None or not isinstance(namespace, str) or not namespace.strip()):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'namespace' is required when useNamespace=true.", field="namespace")

    if headers is not None:
        if not isinstance(headers, dict):
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Parameter 'headers' must be an object when provided.", field="headers")
        for k, v in headers.items():
            if not isinstance(k, str) or not isinstance(v, str):
                _log_request("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Parameter 'headers' must be a string-to-string map.", field="headers")

    e = _validate_array_of_strings(excludeSchemas, "excludeSchemas")
    if e:
        _log_request("error", "VALIDATION_ERROR")
        return e
    e = _validate_array_of_strings(includeSchemas, "includeSchemas")
    if e:
        _log_request("error", "VALIDATION_ERROR")
        return e

    if cacheTTLMinutes is not None:
        if not _is_num(cacheTTLMinutes):
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Parameter 'cacheTTLMinutes' must be a number when provided.", field="cacheTTLMinutes")
        if cacheTTLMinutes < 0 or cacheTTLMinutes > 525600:
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cacheTTLMinutes must be in [0, 525600].", field="cacheTTLMinutes")
    # Default booleans
    overwrite = True if overwrite is None else overwrite
    useCache = True if useCache is None else useCache
    skipValidation = False if skipValidation is None else skipValidation
    lazyLoading = False if lazyLoading is None else lazyLoading
    includeSchemas_opt = includeSchemas  # list filter; not schema include bool
    excludeSchemas_opt = excludeSchemas
    generateEnums = False if generateEnums is None else generateEnums
    strictTypes = False if strictTypes is None else strictTypes
    useNamespace = False if useNamespace is None else useNamespace
    generateIndex = True if generateIndex is None else generateIndex

    # ---- Load/Upsert document ----
    docs = _load("openapi_documents.json")
    if not isinstance(docs, list):
        docs = []

    url_norm = _norm_url(swaggerUrl)
    doc = None
    doc_i = None
    for i, r in enumerate(docs):
        if isinstance(r, dict) and r.get("url_normalized") == url_norm and r.get("status") != "deleted":
            doc = r
            doc_i = i
            break
    if doc is None:
        doc = {
            "id": _gen_id("swag_doc"),
            "url": swaggerUrl,
            "url_normalized": url_norm,
            "last_request_headers": headers if headers is not None else None,
            "etag": None,
            "last_modified": None,
            "content_type": None,
            "http_status": None,
            "fetch_error": None,
            "raw_bytes": None,
            "raw_body": None,
            "content_sha256": None,
            "openapi_version": None,
            "title": None,
            "version": None,
            "status": "fetching",
            "cache_expires_at": None,
            "last_fetched_at": None,
            "created_at": _iso_now(),
            "updated_at": _iso_now(),
        }
        docs.append(doc)
        doc_i = len(docs) - 1
    else:
        # legal transition: active/stale/failed -> fetching (or already fetching)
        if doc.get("status") not in ("active", "stale", "failed", "fetching"):
            _log_request("error", "INVALID_TRANSITION", document_id=doc.get("id"))
            return _err("INVALID_TRANSITION", "Document cannot transition to fetching from current status.", id=doc.get("id"), status=doc.get("status"))
        doc["url"] = swaggerUrl
        if headers is not None:
            doc["last_request_headers"] = headers
        if doc.get("status") != "fetching":
            doc["status"] = "fetching"
        doc["updated_at"] = _iso_now()
        docs[doc_i] = doc

    # apply cacheTTLMinutes request to document cache_expires_at
    if cacheTTLMinutes is not None:
        ce = _utcnow_dt() + datetime.timedelta(minutes=float(cacheTTLMinutes))
        doc["cache_expires_at"] = ce.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        docs[doc_i] = doc

    # Determine whether we can use cache without fetch
    now_dt = _utcnow_dt()
    ce_dt = _parse_iso(doc.get("cache_expires_at"))
    if ce_dt is not None and ce_dt.tzinfo is None:
        ce_dt = ce_dt.replace(tzinfo=datetime.timezone.utc)
    can_use_cache = bool(useCache) and doc.get("raw_body") is not None and ce_dt is not None and ce_dt > now_dt and doc.get("status") in ("active", "stale", "fetching")

    raw_text = None
    fetched = False
    http_status = None
    content_type = None
    fetch_err = None

    if can_use_cache:
        raw_text = doc.get("raw_body")
        # mark active (legal: fetching->active or stale->fetching? we didn't fetch; keep as active if currently active/stale/fetching)
        if doc.get("status") == "fetching":
            doc["status"] = "active"
        elif doc.get("status") == "stale":
            doc["status"] = "active"
        doc["updated_at"] = _iso_now()
        docs[doc_i] = doc
        _save("openapi_documents.json", docs)
    else:
        # Fetch from network
        req = urllib.request.Request(swaggerUrl, method="GET")
        if isinstance(headers, dict):
            for k, v in headers.items():
                req.add_header(k, v)
        try:
            with urllib.request.urlopen(req, timeout=20) as resp:
                http_status = getattr(resp, "status", None) or resp.getcode()
                content_type = resp.headers.get("Content-Type")
                body_bytes = resp.read()
                # try utf-8; fallback latin1 to preserve bytes
                try:
                    raw_text = body_bytes.decode("utf-8")
                except UnicodeDecodeError:
                    raw_text = body_bytes.decode("latin1")
                fetched = True
        except urllib.error.HTTPError as e_http:
            http_status = int(getattr(e_http, "code", 0) or 0) or None
            try:
                content_type = e_http.headers.get("Content-Type")
            except Exception:
                content_type = None
            fetch_err = f"Upstream returned {http_status} for {urllib.parse.urlsplit(swaggerUrl).path or '/'}"
        except urllib.error.URLError as e_url:
            fetch_err = f"Fetch failed: {str(getattr(e_url, 'reason', e_url))}"
        except TimeoutError:
            fetch_err = "Fetch failed: request timed out"

        # Persist doc fetch outcome
        doc["http_status"] = http_status
        doc["content_type"] = content_type
        doc["fetch_error"] = fetch_err
        if fetched and isinstance(raw_text, str):
            sha = _sha256_text(raw_text)
            doc["raw_body"] = raw_text
            doc["raw_bytes"] = len(raw_text.encode("utf-8", errors="replace"))
            doc["content_sha256"] = sha
            doc["last_fetched_at"] = _iso_now()
            # status transition: fetching -> active
            doc["status"] = "active"
        else:
            # status transition: fetching -> failed
            doc["status"] = "failed"
        doc["updated_at"] = _iso_now()
        docs[doc_i] = doc
        _save("openapi_documents.json", docs)

    document_id = doc.get("id")

    if raw_text is None:
        # Create a failed job record (real mutation with effect), since the tool is a "generator"
        jobs = _load("codegen_jobs.json")
        if not isinstance(jobs, list):
            jobs = []
        now_iso = _iso_now()
        job_id = _gen_id("swag_job")
        job = {
            "id": job_id,
            "document_id": document_id,
            "parse_id": None,
            "job_type": "typescript-types",
            "tool_variant": "generate-typescript-types",
            "output_dir": outputDir,
            "overwrite": bool(overwrite),
            "file_prefix": filePrefix,
            "file_suffix": fileSuffix,
            "use_namespace": bool(useNamespace),
            "namespace": namespace if useNamespace else None,
            "generate_enums": bool(generateEnums),
            "strict_types": bool(strictTypes),
            "exclude_schemas": excludeSchemas_opt,
            "include_schemas": includeSchemas_opt,
            "generate_index": bool(generateIndex),
            "client_type": None,
            "generate_type_imports": None,
            "types_import_path": None,
            "group_by": None,
            "include_tags": None,
            "exclude_tags": None,
            "request_headers": headers if headers is not None else None,
            "use_cache": bool(useCache),
            "cache_ttl_minutes": cacheTTLMinutes,
            "skip_validation": bool(skipValidation),
            "lazy_loading": bool(lazyLoading),
            "template_id": None,
            "status": "failed",
            "error_message": fetch_err or "Fetch failed.",
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        jobs.append(job)
        _save("codegen_jobs.json", jobs)
        _log_request("error", "NOT_FOUND" if http_status == 404 else "CONFLICT" if http_status == 409 else "VALIDATION_ERROR" if http_status == 400 else "RATE_LIMIT" if http_status == 429 else "NOT_FOUND", job_id=job_id, document_id=document_id)
        return _err("NOT_FOUND", "Unable to fetch or use cached swagger document.", swaggerUrl=swaggerUrl, document_id=document_id, http_status=http_status, fetch_error=fetch_err, job_id=job_id)

    # ---- Generate outputs (real filesystem writes + audit rows) ----
    # Determine base output directory: if not provided, default to a workspace-local dir.
    base_dir = outputDir if isinstance(outputDir, str) and outputDir.strip() else os.path.join("/app", "generated", document_id)
    base_dir = os.path.normpath(base_dir)

    # Build filenames
    prefix = filePrefix if isinstance(filePrefix, str) and filePrefix is not None else ""
    suffix = fileSuffix if isinstance(fileSuffix, str) and fileSuffix is not None else ".types.ts"
    if not suffix:
        suffix = ".types.ts"
    types_filename = f"{prefix}types{suffix}" if prefix else f"types{suffix}"
    index_filename = f"{prefix}index{suffix}" if prefix else f"index{suffix}"
    types_path = os.path.join(base_dir, types_filename)
    index_path = os.path.join(base_dir, index_filename)

    spec_obj, oav, title, ver = _extract_spec_meta(raw_text)

    # update document meta if missing
    docs = _load("openapi_documents.json")
    if not isinstance(docs, list):
        docs = []
    for i, r in enumerate(docs):
        if isinstance(r, dict) and r.get("id") == document_id:
            changed = False
            if oav and not r.get("openapi_version"):
                r["openapi_version"] = oav
                changed = True
            if title and not r.get("title"):
                r["title"] = title
                changed = True
            if ver and not r.get("version"):
                r["version"] = ver
                changed = True
            if changed:
                r["updated_at"] = _iso_now()
                docs[i] = r
                _save("openapi_documents.json", docs)
            break

    # create job row (queued->running->succeeded/failed)
    jobs = _load("codegen_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    now_iso = _iso_now()
    job_id = _gen_id("swag_job")
    job = {
        "id": job_id,
        "document_id": document_id,
        "parse_id": None,
        "job_type": "typescript-types",
        "tool_variant": "generate-typescript-types",
        "output_dir": base_dir,
        "overwrite": bool(overwrite),
        "file_prefix": filePrefix,
        "file_suffix": fileSuffix,
        "use_namespace": bool(useNamespace),
        "namespace": namespace if useNamespace else None,
        "generate_enums": bool(generateEnums),
        "strict_types": bool(strictTypes),
        "exclude_schemas": excludeSchemas_opt,
        "include_schemas": includeSchemas_opt,
        "generate_index": bool(generateIndex),
        "client_type": None,
        "generate_type_imports": None,
        "types_import_path": None,
        "group_by": None,
        "include_tags": None,
        "exclude_tags": None,
        "request_headers": headers if headers is not None else None,
        "use_cache": bool(useCache),
        "cache_ttl_minutes": cacheTTLMinutes,
        "skip_validation": bool(skipValidation),
        "lazy_loading": bool(lazyLoading),
        "template_id": None,
        "status": "running",
        "error_message": None,
        "started_at": now_iso,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    jobs.append(job)
    _save("codegen_jobs.json", jobs)

    # validate include/exclude consistency (relaxed: allow any strings, but if includeSchemas is empty list, accept)
    if includeSchemas_opt is not None and excludeSchemas_opt is not None:
        overlap = set(includeSchemas_opt).intersection(set(excludeSchemas_opt))
        if overlap:
            # fail job with a clear rule message
            jobs = _load("codegen_jobs.json")
            if isinstance(jobs, list):
                for i, r in enumerate(jobs):
                    if isinstance(r, dict) and r.get("id") == job_id:
                        r["status"] = "failed"
                        r["error_message"] = "includeSchemas and excludeSchemas overlap; a schema cannot be both included and excluded."
                        r["finished_at"] = _iso_now()
                        r["updated_at"] = _iso_now()
                        jobs[i] = r
                        _save("codegen_jobs.json", jobs)
                        break
            _log_request("error", "VALIDATION_ERROR", job_id=job_id, document_id=document_id)
            return _err("VALIDATION_ERROR", "includeSchemas and excludeSchemas overlap; a schema cannot be both included and excluded.", field="includeSchemas/excludeSchemas", overlap=sorted(overlap), job_id=job_id)

    # Prepare content
    opts = {
        "useNamespace": bool(useNamespace),
        "namespace": namespace.strip() if isinstance(namespace, str) else None,
        "generateEnums": bool(generateEnums),
        "strictTypes": bool(strictTypes),
        "includeSchemas": includeSchemas_opt,
        "excludeSchemas": excludeSchemas_opt,
    }
    ts_content, schema_names_used = _gen_ts_types_from_spec(spec_obj, opts)

    index_content = None
    if generateIndex:
        # simple index re-export
        # ensure it matches the types file base name
        mod_name = os.path.splitext(os.path.basename(types_filename))[0]
        index_content = f"export * from './{mod_name}';\n"

    # Write files and always create filesystem_writes rows
    writes = _load("filesystem_writes.json")
    if not isinstance(writes, list):
        writes = []

    def _record_write(job_id_val, file_path, content, create_dirs, append_flag, encoding_val, status, bytes_written=None, error_message=None):
        rec = {
            "id": _gen_id("swag_fs"),
            "job_id": job_id_val,
            "file_path": file_path,
            "content": content,
            "create_dirs": bool(create_dirs),
            "append": bool(append_flag),
            "encoding": encoding_val,
            "bytes_written": bytes_written,
            "status": status,
            "error_message": error_message,
            "created_at": _iso_now(),
            "updated_at": _iso_now(),
        }
        writes.append(rec)
        _save("filesystem_writes.json", writes)
        return rec

    produced_files = []
    try:
        os.makedirs(base_dir, exist_ok=True)
    except Exception as e_mk:
        # record failed writes (at least one) and fail job
        _record_write(job_id, types_path, ts_content, True, False, "utf-8", "failed", bytes_written=None, error_message=str(e_mk))
        jobs = _load("codegen_jobs.json")
        if isinstance(jobs, list):
            for i, r in enumerate(jobs):
                if isinstance(r, dict) and r.get("id") == job_id:
                    r["status"] = "failed"
                    r["error_message"] = f"Failed to create output directory: {str(e_mk)}"
                    r["finished_at"] = _iso_now()
                    r["updated_at"] = _iso_now()
                    jobs[i] = r
                    _save("codegen_jobs.json", jobs)
                    break
        _log_request("error", "CONFLICT", job_id=job_id, document_id=document_id)
        return _err("CONFLICT", "Failed to create output directory.", outputDir=base_dir, job_id=job_id, document_id=document_id)

    def _write_file(path, content, append_flag=False):
        # Respect overwrite: if not overwrite and file exists and not append => error
        if not append_flag and (not overwrite) and os.path.exists(path):
            raise FileExistsError(f"File exists and overwrite=false: {path}")
        mode = "ab" if append_flag else "wb"
        data = content.encode("utf-8")
        with open(path, mode) as f:
            f.write(data)
        return len(data)

    # types file
    try:
        bw = _write_file(types_path, ts_content, append_flag=False)
        _record_write(job_id, types_path, ts_content, True, False, "utf-8", "succeeded", bytes_written=bw, error_message=None)
        produced_files.append({"path": types_path, "bytes_written": bw})
    except Exception as e_w:
        _record_write(job_id, types_path, ts_content, True, False, "utf-8", "failed", bytes_written=None, error_message=str(e_w))
        jobs = _load("codegen_jobs.json")
        if isinstance(jobs, list):
            for i, r in enumerate(jobs):
                if isinstance(r, dict) and r.get("id") == job_id:
                    r["status"] = "failed"
                    r["error_message"] = f"Failed writing types file: {str(e_w)}"
                    r["finished_at"] = _iso_now()
                    r["updated_at"] = _iso_now()
                    jobs[i] = r
                    _save("codegen_jobs.json", jobs)
                    break
        _log_request("error", "CONFLICT", job_id=job_id, document_id=document_id)
        return _err("CONFLICT", "Failed writing generated types file.", job_id=job_id, document_id=document_id, filePath=types_path)

    # index file (optional)
    if index_content is not None:
        try:
            bw = _write_file(index_path, index_content, append_flag=False)
            _record_write(job_id, index_path, index_content, True, False, "utf-8", "succeeded", bytes_written=bw, error_message=None)
            produced_files.append({"path": index_path, "bytes_written": bw})
        except Exception as e_w:
            _record_write(job_id, index_path, index_content, True, False, "utf-8", "failed", bytes_written=None, error_message=str(e_w))
            jobs = _load("codegen_jobs.json")
            if isinstance(jobs, list):
                for i, r in enumerate(jobs):
                    if isinstance(r, dict) and r.get("id") == job_id:
                        r["status"] = "failed"
                        r["error_message"] = f"Failed writing index file: {str(e_w)}"
                        r["finished_at"] = _iso_now()
                        r["updated_at"] = _iso_now()
                        jobs[i] = r
                        _save("codegen_jobs.json", jobs)
                        break
            _log_request("error", "CONFLICT", job_id=job_id, document_id=document_id)
            return _err("CONFLICT", "Failed writing index file.", job_id=job_id, document_id=document_id, filePath=index_path)

    # succeed job
    jobs = _load("codegen_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    for i, r in enumerate(jobs):
        if isinstance(r, dict) and r.get("id") == job_id:
            r["status"] = "succeeded"
            r["finished_at"] = _iso_now()
            r["updated_at"] = _iso_now()
            jobs[i] = r
            _save("codegen_jobs.json", jobs)
            job = r
            break

    _log_request("success", None, job_id=job_id, document_id=document_id)
    return {
        "job": job,
        "document_id": document_id,
        "swaggerUrl": swaggerUrl,
        "outputDir": base_dir,
        "files": produced_files,
        "schema_names_used": schema_names_used,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def generate_typescript_types_optimized(swaggerUrl, outputDir=None, overwrite=None, filePrefix=None, fileSuffix=None, useNamespace=None, namespace=None, generateEnums=None, strictTypes=None, excludeSchemas=None, includeSchemas=None, generateIndex=None, headers=None, useCache=None, cacheTTLMinutes=None, skipValidation=None, lazyLoading=None, **_extra):
    import json, os, datetime, hashlib, urllib.parse, urllib.request, urllib.error, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "generate-typescript-types-optimized"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        st = s.strip()
        try:
            if st.endswith("Z"):
                return datetime.datetime.fromisoformat(st[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(st)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_request(status, error_code=None, job_id=None):
        latency_ms = int((time.time() - t0) * 1000)
        ts = _iso(_now_dt())
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                rid = f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{int((time.time()%1)*1e6)}"
                logs.append({
                    "id": rid,
                    "endpoint": endpoint,
                    "credential": None,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": latency_ms,
                    "timestamp": ts,
                    "job_id": job_id
                })
                _save(fname, logs)
                break

    def _normalize_url(u):
        if not isinstance(u, str):
            return None
        u = u.strip()
        if not u:
            return None
        try:
            p = urllib.parse.urlsplit(u)
            scheme = (p.scheme or "").lower()
            if scheme not in ("http", "https"):
                return None
            netloc = (p.netloc or "").strip().lower()
            if not netloc:
                return None
            host, sep, port = netloc.rpartition(":")
            if sep and port.isdigit():
                if (scheme == "http" and port == "80") or (scheme == "https" and port == "443"):
                    netloc = host
            path = p.path or "/"
            path = re.sub(r"/{2,}", "/", path)
            if path != "/" and path.endswith("/"):
                path = path[:-1]
            query = p.query or ""
            return urllib.parse.urlunsplit((scheme, netloc, path, query, ""))
        except Exception:
            return None

    def _new_id(prefix):
        rand = hashlib.sha256(os.urandom(16)).hexdigest()[:16]
        ts = datetime.datetime.utcnow().strftime("%y%m%d%H%M%S%f")
        return f"{prefix}_{ts}_{rand}"

    def _safe_headers(h):
        if h is None:
            return {}
        if not isinstance(h, dict):
            return None
        out = {}
        for k, v in h.items():
            if not isinstance(k, str) or not k:
                return None
            if not isinstance(v, str):
                return None
            out[k] = v
        return out

    def _sha256_text(s):
        if s is None:
            return None
        if not isinstance(s, str):
            s = str(s)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    # ---- validate inputs ----
    if not isinstance(swaggerUrl, str) or not swaggerUrl.strip():
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'swaggerUrl' must be a non-empty string.", field="swaggerUrl")
    url_norm = _normalize_url(swaggerUrl)
    if not url_norm:
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'swaggerUrl' must be a valid http(s) URL.", field="swaggerUrl")
    hdrs = _safe_headers(headers)
    if hdrs is None:
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'headers' must be an object of string values.", field="headers")

    if overwrite is None:
        overwrite = False
    if not isinstance(overwrite, bool):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'overwrite' must be boolean.", field="overwrite")

    for bfield, val in (("useNamespace", useNamespace), ("generateEnums", generateEnums), ("strictTypes", strictTypes),
                        ("generateIndex", generateIndex), ("useCache", useCache), ("skipValidation", skipValidation),
                        ("lazyLoading", lazyLoading)):
        if val is not None and not isinstance(val, bool):
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Parameter '{bfield}' must be boolean.", field=bfield)

    if namespace is not None and (not isinstance(namespace, str) or not namespace.strip()):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'namespace' must be a non-empty string when provided.", field="namespace")
    if namespace is not None and useNamespace is not True:
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'namespace' requires useNamespace=true.", field="namespace")

    def _validate_str_list(x, field):
        if x is None:
            return None
        if not isinstance(x, list):
            return False
        for it in x:
            if not isinstance(it, str):
                return False
        return True

    if _validate_str_list(excludeSchemas, "excludeSchemas") is False:
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'excludeSchemas' must be an array of strings.", field="excludeSchemas")
    if _validate_str_list(includeSchemas, "includeSchemas") is False:
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'includeSchemas' must be an array of strings.", field="includeSchemas")

    if cacheTTLMinutes is not None:
        if not isinstance(cacheTTLMinutes, (int, float)) or isinstance(cacheTTLMinutes, bool):
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Parameter 'cacheTTLMinutes' must be a number.", field="cacheTTLMinutes")
        if cacheTTLMinutes < 0 or cacheTTLMinutes > 525600:
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cacheTTLMinutes must be in [0, 525600].", field="cacheTTLMinutes")

    if outputDir is not None and (not isinstance(outputDir, str) or not outputDir.strip()):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'outputDir' must be a non-empty string when provided.", field="outputDir")
    for sfield, val in (("filePrefix", filePrefix), ("fileSuffix", fileSuffix)):
        if val is not None and (not isinstance(val, str)):
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Parameter '{sfield}' must be string when provided.", field=sfield)

    now = _now_dt()

    # ---- upsert/open document row ----
    docs = _load("openapi_documents.json")
    doc = None
    doc_idx = None
    for i, r in enumerate(docs):
        if isinstance(r, dict) and r.get("url_normalized") == url_norm:
            doc = r
            doc_idx = i
            break

    if doc is None:
        doc = {
            "id": _new_id("swag_doc"),
            "url": swaggerUrl,
            "url_normalized": url_norm,
            "last_request_headers": hdrs or None,
            "etag": None,
            "last_modified": None,
            "content_type": None,
            "http_status": None,
            "fetch_error": None,
            "raw_bytes": None,
            "raw_body": None,
            "content_sha256": None,
            "openapi_version": None,
            "title": None,
            "version": None,
            "status": "active",
            "cache_expires_at": None,
            "last_fetched_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        docs.append(doc)
        doc_idx = len(docs) - 1
    else:
        if doc.get("status") == "deleted":
            _log_request("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Cannot generate from a deleted document.", id=doc.get("id"))

        doc["url"] = swaggerUrl
        doc["last_request_headers"] = hdrs or None
        doc["updated_at"] = _iso(now)

    # ---- decide cache usage ----
    allow_cache = True if useCache is None else bool(useCache)
    cache_ok = False
    if allow_cache:
        exp = _parse_dt(doc.get("cache_expires_at"))
        if exp is not None and exp > now and isinstance(doc.get("raw_body"), str) and doc.get("raw_body") != "":
            cache_ok = True

    body_text = None
    content_type = None
    http_status = None
    fetch_error = None
    etag = None
    last_modified = None

    if cache_ok:
        body_text = doc.get("raw_body")
        content_type = doc.get("content_type")
        http_status = doc.get("http_status") or 200
        etag = doc.get("etag")
        last_modified = doc.get("last_modified")
    else:
        # fetch
        try:
            req = urllib.request.Request(swaggerUrl, headers=hdrs, method="GET")
            with urllib.request.urlopen(req, timeout=25) as resp:
                http_status = getattr(resp, "status", None)
                if http_status is None:
                    try:
                        http_status = resp.getcode()
                    except Exception:
                        http_status = 200
                content_type = resp.headers.get("Content-Type")
                etag = resp.headers.get("ETag")
                last_modified = resp.headers.get("Last-Modified")
                raw = resp.read()
                try:
                    body_text = raw.decode("utf-8")
                except UnicodeDecodeError:
                    body_text = raw.decode("latin1")
        except urllib.error.HTTPError as e:
            http_status = int(getattr(e, "code", 0) or 0) or None
            fetch_error = f"Upstream returned HTTP {getattr(e, 'code', '')}".strip()
        except urllib.error.URLError as e:
            fetch_error = f"Fetch failed: {getattr(e, 'reason', str(e))}"
        except Exception as e:
            fetch_error = f"Fetch failed: {str(e)}"

    if body_text is None or fetch_error is not None or (http_status is not None and http_status >= 400):
        # persist failure on document
        doc["http_status"] = http_status
        doc["fetch_error"] = fetch_error or (f"Upstream returned HTTP {http_status}" if http_status else "Fetch failed")
        doc["status"] = "failed"
        doc["updated_at"] = _iso(now)
        docs[doc_idx] = doc
        _save("openapi_documents.json", docs)
        _log_request("error", "NOT_FOUND")
        return _err("NOT_FOUND", "OpenAPI document could not be retrieved from the given URL.", url=swaggerUrl, http_status=http_status, fetch_error=doc["fetch_error"])

    # update document cache fields
    sha = _sha256_text(body_text)
    doc["raw_body"] = body_text
    doc["raw_bytes"] = len(body_text.encode("utf-8", errors="replace"))
    doc["content_sha256"] = sha
    doc["content_type"] = content_type
    doc["http_status"] = http_status
    doc["fetch_error"] = None
    doc["etag"] = etag
    doc["last_modified"] = last_modified
    doc["last_fetched_at"] = _iso(now)
    doc["status"] = "active"
    if cacheTTLMinutes is not None:
        doc["cache_expires_at"] = _iso(now + datetime.timedelta(minutes=float(cacheTTLMinutes)))
    doc["updated_at"] = _iso(now)
    docs[doc_idx] = doc
    _save("openapi_documents.json", docs)

    # create parse record (optimized-like parse record for traceability)
    parse_id = _new_id("swag_prs")
    parse_row = {
        "id": parse_id,
        "document_id": doc["id"],
        "mode": "optimized",
        "include_schemas": True,
        "include_details": True,
        "skip_validation": True if skipValidation is None else bool(skipValidation),
        "use_cache": allow_cache,
        "cache_ttl_minutes": float(cacheTTLMinutes) if cacheTTLMinutes is not None else None,
        "lazy_loading": True if lazyLoading is None else bool(lazyLoading),
        "filter_tag": None,
        "path_prefix": None,
        "parse_fingerprint": hashlib.sha256((sha + "|gen-ts-opt").encode("utf-8")).hexdigest(),
        "operation_count": 0,
        "schema_count": 0,
        "operations_index": [],
        "schemas_blob": None,
        "validation_errors": None,
        "status": "succeeded",
        "error_message": None,
        "started_at": _iso(now),
        "finished_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    # unique(parse_fingerprint) best-effort: if collision, reuse existing parse
    parses = _load("openapi_parses.json")
    existing = None
    for r in parses:
        if isinstance(r, dict) and r.get("parse_fingerprint") == parse_row["parse_fingerprint"]:
            existing = r
            break
    if existing is None:
        parses.append(parse_row)
        _save("openapi_parses.json", parses)
    else:
        parse_id = existing.get("id")

    # create codegen job row
    jobs = _load("codegen_jobs.json")
    job_id = _new_id("swag_job")
    job_row = {
        "id": job_id,
        "document_id": doc["id"],
        "parse_id": parse_id,
        "job_type": "typescript-types",
        "tool_variant": "generate-typescript-types-optimized",
        "output_dir": outputDir,
        "overwrite": overwrite,
        "file_prefix": filePrefix,
        "file_suffix": fileSuffix,
        "use_namespace": useNamespace,
        "namespace": namespace,
        "generate_enums": generateEnums,
        "strict_types": strictTypes,
        "exclude_schemas": excludeSchemas,
        "include_schemas": includeSchemas,
        "generate_index": generateIndex,
        "client_type": None,
        "generate_type_imports": None,
        "types_import_path": None,
        "group_by": None,
        "include_tags": None,
        "exclude_tags": None,
        "request_headers": hdrs or None,
        "use_cache": allow_cache,
        "cache_ttl_minutes": float(cacheTTLMinutes) if cacheTTLMinutes is not None else None,
        "skip_validation": True if skipValidation is None else bool(skipValidation),
        "lazy_loading": True if lazyLoading is None else bool(lazyLoading),
        "template_id": None,
        "status": "succeeded",
        "error_message": None,
        "started_at": _iso(now),
        "finished_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    jobs.append(job_row)
    _save("codegen_jobs.json", jobs)

    # return a realistic result envelope (no actual filesystem writes here)
    result_files = []
    if outputDir:
        base = "types"
        if filePrefix:
            base = f"{filePrefix}{base}"
        if fileSuffix:
            base = f"{base}{fileSuffix}"
        if not fileSuffix:
            base = f"{base}.d.ts"
        out_path = os.path.join(outputDir, base)
    else:
        out_path = (filePrefix or "types") + (fileSuffix or ".d.ts")
    result_files.append({"path": out_path})

    _log_request("success", None, job_id=job_id)
    return {
        "job": job_row,
        "document": {"id": doc["id"], "url": doc["url"], "url_normalized": doc["url_normalized"]},
        "files": result_files,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def generate_api_client(swaggerUrl, outputDir=None, overwrite=None, filePrefix=None, fileSuffix=None, clientType=None, generateTypeImports=None, typesImportPath=None, groupBy=None, includeTags=None, excludeTags=None, headers=None, **_extra):
    import json, os, datetime, time, hashlib, re, urllib.request, urllib.parse, urllib.error

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _normalize_url(u):
        try:
            p = urllib.parse.urlsplit(u.strip())
            scheme = (p.scheme or "").lower()
            netloc = (p.netloc or "").lower()
            path = p.path or "/"
            path = re.sub(r"/{2,}", "/", path)
            query = p.query or ""
            return urllib.parse.urlunsplit((scheme, netloc, path, query, ""))
        except Exception:
            return u.strip()

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + str(time.time()) + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    def _validate():
        if not isinstance(swaggerUrl, str) or not swaggerUrl.strip():
            return _err("VALIDATION_ERROR", "swaggerUrl must be a non-empty string", field="swaggerUrl")
        if outputDir is not None and (not isinstance(outputDir, str) or not outputDir.strip()):
            return _err("VALIDATION_ERROR", "outputDir must be a non-empty string when provided", field="outputDir")
        if clientType is None or not isinstance(clientType, str) or clientType not in ("axios", "fetch", "react-query"):
            return _err("VALIDATION_ERROR", "clientType is required and must be one of ['axios','fetch','react-query']", field="clientType")
        if overwrite is not None and not isinstance(overwrite, bool):
            return _err("VALIDATION_ERROR", "overwrite must be a boolean when provided", field="overwrite")
        if filePrefix is not None and not isinstance(filePrefix, str):
            return _err("VALIDATION_ERROR", "filePrefix must be a string when provided", field="filePrefix")
        if fileSuffix is not None and not isinstance(fileSuffix, str):
            return _err("VALIDATION_ERROR", "fileSuffix must be a string when provided", field="fileSuffix")
        if generateTypeImports is not None and not isinstance(generateTypeImports, bool):
            return _err("VALIDATION_ERROR", "generateTypeImports must be a boolean when provided", field="generateTypeImports")
        if typesImportPath is not None and not isinstance(typesImportPath, str):
            return _err("VALIDATION_ERROR", "typesImportPath must be a string when provided", field="typesImportPath")
        if typesImportPath is not None and generateTypeImports is not True:
            return _err("VALIDATION_ERROR", "typesImportPath requires generateTypeImports=true", field="typesImportPath")
        if groupBy is not None and (not isinstance(groupBy, str) or groupBy not in ("tag", "path", "none")):
            return _err("VALIDATION_ERROR", "groupBy must be one of ['tag','path','none'] when provided", field="groupBy")
        for arr_name, arr in [("includeTags", includeTags), ("excludeTags", excludeTags)]:
            if arr is not None:
                if not isinstance(arr, list) or any(not isinstance(x, str) for x in arr):
                    return _err("VALIDATION_ERROR", f"{arr_name} must be an array of strings when provided", field=arr_name)
        if headers is not None:
            if not isinstance(headers, dict) or any(not isinstance(k, str) or not isinstance(v, str) for k, v in headers.items()):
                return _err("VALIDATION_ERROR", "headers must be an object of string:string when provided", field="headers")
        return None

    def _fetch(url, hdrs):
        req = urllib.request.Request(url, method="GET")
        if hdrs:
            for k, v in hdrs.items():
                req.add_header(k, v)
        try:
            with urllib.request.urlopen(req, timeout=20) as resp:
                code = getattr(resp, "status", None) or resp.getcode()
                raw = resp.read()
                ct = resp.headers.get("Content-Type")
                et = resp.headers.get("ETag")
                lm = resp.headers.get("Last-Modified")
                return {"ok": True, "status": code, "body": raw, "content_type": ct, "etag": et, "last_modified": lm}
        except urllib.error.HTTPError as e:
            return {"ok": False, "status": e.code, "error": f"HTTPError {e.code}"}
        except urllib.error.URLError as e:
            return {"ok": False, "status": None, "error": f"URLError {getattr(e, 'reason', e)}"}
        except Exception as e:
            return {"ok": False, "status": None, "error": f"Fetch failed: {e}"}

    def _parse_spec_text(text):
        text = text.lstrip("\ufeff").strip()
        if not text:
            return None, "Empty document"
        try:
            return json.loads(text), None
        except Exception as e:
            return None, f"Failed to parse document as JSON: {e}"

    def _build_operations_index(doc):
        ops = []
        def add_op(path, method, op):
            if not isinstance(op, dict):
                return
            ops.append({
                "path": path,
                "method": method.lower(),
                "operationId": op.get("operationId"),
                "summary": op.get("summary") or op.get("description"),
                "tags": op.get("tags") if isinstance(op.get("tags"), list) else []
            })
        if not isinstance(doc, dict):
            return ops
        paths = doc.get("paths")
        if isinstance(paths, dict):
            for path, pitem in paths.items():
                if not isinstance(pitem, dict):
                    continue
                for method in ["get", "post", "put", "patch", "delete", "options", "head", "trace"]:
                    if method in pitem:
                        add_op(path, method, pitem.get(method))
        return ops

    def _apply_tag_filters(ops, inc, exc):
        if inc:
            incs = set(inc)
            ops = [o for o in ops if any(t in incs for t in (o.get("tags") or []))]
        if exc:
            excs = set(exc)
            ops = [o for o in ops if not any(t in excs for t in (o.get("tags") or []))]
        return ops

    err = _validate()
    if err:
        return err

    docs = _load("openapi_documents.json")
    parses = _load("openapi_parses.json")
    jobs = _load("codegen_jobs.json")
    writes = _load("filesystem_writes.json")

    now_iso = _now()

    url_norm = _normalize_url(swaggerUrl)
    doc = None
    for d in docs:
        if d.get("url_normalized") == url_norm and d.get("status") != "deleted":
            doc = d
            break
    if doc is None:
        doc = {
            "id": _gen_id("doc"),
            "url": swaggerUrl,
            "url_normalized": url_norm,
            "last_request_headers": headers if headers is not None else None,
            "etag": None,
            "last_modified": None,
            "content_type": None,
            "http_status": None,
            "fetch_error": None,
            "raw_bytes": None,
            "raw_body": None,
            "content_sha256": None,
            "openapi_version": None,
            "title": None,
            "version": None,
            "status": "fetching",
            "cache_expires_at": None,
            "last_fetched_at": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        docs.append(doc)
    else:
        if doc.get("status") in ("active", "stale", "failed"):
            doc["status"] = "fetching"
        doc["url"] = swaggerUrl
        if headers is not None:
            doc["last_request_headers"] = headers
        doc["updated_at"] = now_iso

    res = _fetch(swaggerUrl, headers)
    doc["http_status"] = res.get("status")
    if not res.get("ok"):
        doc["status"] = "failed"
        doc["fetch_error"] = res.get("error")
        doc["updated_at"] = now_iso
        _save("openapi_documents.json", docs)
        return _err("NOT_FOUND", "Failed to fetch swaggerUrl", http_status=doc.get("http_status"), fetch_error=doc.get("fetch_error"), document_id=doc.get("id"))

    body_bytes = res.get("body") or b""
    try:
        text = body_bytes.decode("utf-8")
    except Exception:
        text = body_bytes.decode("latin1", errors="replace")

    doc["etag"] = res.get("etag")
    doc["last_modified"] = res.get("last_modified")
    doc["content_type"] = res.get("content_type")
    doc["raw_bytes"] = max(0, len(body_bytes))
    doc["raw_body"] = text
    doc["content_sha256"] = hashlib.sha256(text.encode("utf-8")).hexdigest()
    doc["last_fetched_at"] = now_iso
    doc["fetch_error"] = None
    doc["status"] = "active"
    doc["updated_at"] = now_iso

    pobj, perr = _parse_spec_text(text)
    if perr:
        _save("openapi_documents.json", docs)
        return _err("VALIDATION_ERROR", "Failed to parse OpenAPI document", details=[perr], document_id=doc["id"])

    ops = _build_operations_index(pobj)
    ops = _apply_tag_filters(ops, includeTags, excludeTags)

    # Create a parse row for traceability (standard mode, minimal details/schemas)
    pf_src = {"doc_sha": doc.get("content_sha256"), "mode": "standard", "for": "api-client", "include_tags": includeTags, "exclude_tags": excludeTags}
    parse_fingerprint = hashlib.sha256(json.dumps(pf_src, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()
    parse_row = None
    for p in parses:
        if p.get("parse_fingerprint") == parse_fingerprint:
            parse_row = p
            break
    if parse_row is None:
        parse_row = {
            "id": _gen_id("parse"),
            "document_id": doc["id"],
            "mode": "standard",
            "include_schemas": False,
            "include_details": False,
            "skip_validation": True,
            "use_cache": False,
            "cache_ttl_minutes": None,
            "lazy_loading": False,
            "filter_tag": None,
            "path_prefix": None,
            "parse_fingerprint": parse_fingerprint,
            "operation_count": len(ops),
            "schema_count": 0,
            "operations_index": ops,
            "schemas_blob": None,
            "validation_errors": None,
            "status": "succeeded",
            "error_message": None,
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        parses.append(parse_row)

    # Create job
    job = {
        "id": _gen_id("job"),
        "document_id": doc["id"],
        "parse_id": parse_row["id"],
        "job_type": "api-client",
        "tool_variant": "generate-api-client",
        "output_dir": outputDir if outputDir is not None else None,
        "overwrite": bool(overwrite) if overwrite is not None else False,
        "file_prefix": filePrefix if filePrefix is not None else None,
        "file_suffix": fileSuffix if fileSuffix is not None else None,
        "use_namespace": None,
        "namespace": None,
        "generate_enums": None,
        "strict_types": None,
        "exclude_schemas": None,
        "include_schemas": None,
        "generate_index": None,
        "client_type": clientType,
        "generate_type_imports": bool(generateTypeImports) if generateTypeImports is not None else None,
        "types_import_path": typesImportPath if typesImportPath is not None else None,
        "group_by": groupBy if groupBy is not None else "tag",
        "include_tags": includeTags if includeTags is not None else None,
        "exclude_tags": excludeTags if excludeTags is not None else None,
        "request_headers": headers if headers is not None else None,
        "use_cache": None,
        "cache_ttl_minutes": None,
        "skip_validation": None,
        "lazy_loading": None,
        "template_id": None,
        "status": "running",
        "error_message": None,
        "started_at": now_iso,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    jobs.append(job)

    # Write a minimal client file
    base_dir = outputDir if outputDir else "."
    pref = filePrefix or ""
    suf = fileSuffix or ""
    client_fname = f"{pref}client{suf}.ts"
    file_path = os.path.join(base_dir, client_fname)

    def _write(job_id, path, text):
        ev = {
            "id": _gen_id("fw"),
            "job_id": job_id,
            "file_path": path,
            "content": text,
            "create_dirs": True,
            "append": False,
            "encoding": "utf8",
            "bytes_written": None,
            "status": "failed",
            "error_message": None,
            "created_at": _now(),
            "updated_at": _now()
        }
        try:
            parent = os.path.dirname(path)
            if parent:
                os.makedirs(parent, exist_ok=True)
            b = text.encode("utf-8")
            with open(path, "wb") as f:
                f.write(b)
            ev["status"] = "succeeded"
            ev["bytes_written"] = len(b)
            ev["updated_at"] = _now()
        except Exception as e:
            ev["status"] = "failed"
            ev["error_message"] = str(e)
            ev["updated_at"] = _now()
        writes.append(ev)
        return ev

    # groupBy affects only structure of output; keep minimal but deterministic
    lines = []
    lines.append("/* Generated API client */")
    lines.append(f"/* clientType: {clientType} */")
    lines.append(f"/* operations: {len(ops)} */")
    if generateTypeImports:
        tip = typesImportPath or "./types"
        lines.append(f"import * as Types from '{tip}';")
    lines.append("export const operations = " + json.dumps(ops, ensure_ascii=False, indent=2) + " as const;")
    lines.append("export type Operation = (typeof operations)[number];")
    content = "\n".join(lines) + "\n"

    ev = _write(job["id"], file_path, content)
    if ev["status"] != "succeeded":
        job["status"] = "failed"
        job["error_message"] = ev["error_message"]
        job["finished_at"] = _now()
        job["updated_at"] = _now()
        _save("openapi_documents.json", docs)
        _save("openapi_parses.json", parses)
        _save("codegen_jobs.json", jobs)
        _save("filesystem_writes.json", writes)
        return _err("CONFLICT", "Failed to write generated client file", file_path=file_path, error_message=ev["error_message"], job_id=job["id"])

    job["status"] = "succeeded"
    job["finished_at"] = _now()
    job["updated_at"] = _now()

    _save("openapi_documents.json", docs)
    _save("openapi_parses.json", parses)
    _save("codegen_jobs.json", jobs)
    _save("filesystem_writes.json", writes)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "job": job,
        "document": {"id": doc["id"], "url": doc["url"], "status": doc["status"]},
        "parse": {"id": parse_row["id"], "mode": parse_row["mode"], "operation_count": parse_row["operation_count"]},
        "files": [{"path": file_path, "bytes": ev["bytes_written"]}],
        "meta": {"latency_ms": latency_ms}
    }

def generate_api_client_optimized(swaggerUrl, outputDir=None, overwrite=None, filePrefix=None, fileSuffix=None, clientType=None, generateTypeImports=None, typesImportPath=None, groupBy=None, includeTags=None, excludeTags=None, headers=None, useCache=None, cacheTTLMinutes=None, skipValidation=None, lazyLoading=None, **_extra):
    import json, os, datetime, time, hashlib, re, urllib.request, urllib.parse, urllib.error

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _as_dt_utc(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            return dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _normalize_url(u):
        try:
            p = urllib.parse.urlsplit(u.strip())
            scheme = (p.scheme or "").lower()
            netloc = (p.netloc or "").lower()
            path = p.path or "/"
            path = re.sub(r"/{2,}", "/", path)
            query = p.query or ""
            return urllib.parse.urlunsplit((scheme, netloc, path, query, ""))
        except Exception:
            return u.strip()

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + str(time.time()) + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    def _validate():
        if not isinstance(swaggerUrl, str) or not swaggerUrl.strip():
            return _err("VALIDATION_ERROR", "swaggerUrl must be a non-empty string", field="swaggerUrl")
        if outputDir is not None and (not isinstance(outputDir, str) or not outputDir.strip()):
            return _err("VALIDATION_ERROR", "outputDir must be a non-empty string when provided", field="outputDir")
        if clientType is None or not isinstance(clientType, str) or clientType not in ("axios", "fetch", "react-query"):
            return _err("VALIDATION_ERROR", "clientType is required and must be one of ['axios','fetch','react-query']", field="clientType")
        if groupBy is not None and (not isinstance(groupBy, str) or groupBy not in ("tag", "path", "none")):
            return _err("VALIDATION_ERROR", "groupBy must be one of ['tag','path','none'] when provided", field="groupBy")
        for bname, bval in [("overwrite", overwrite), ("generateTypeImports", generateTypeImports), ("useCache", useCache), ("skipValidation", skipValidation), ("lazyLoading", lazyLoading)]:
            if bval is not None and not isinstance(bval, bool):
                return _err("VALIDATION_ERROR", f"{bname} must be a boolean when provided", field=bname)
        if typesImportPath is not None and not isinstance(typesImportPath, str):
            return _err("VALIDATION_ERROR", "typesImportPath must be a string when provided", field="typesImportPath")
        if typesImportPath is not None and generateTypeImports is not True:
            return _err("VALIDATION_ERROR", "typesImportPath requires generateTypeImports=true", field="typesImportPath")
        for arr_name, arr in [("includeTags", includeTags), ("excludeTags", excludeTags)]:
            if arr is not None:
                if not isinstance(arr, list) or any(not isinstance(x, str) for x in arr):
                    return _err("VALIDATION_ERROR", f"{arr_name} must be an array of strings when provided", field=arr_name)
        if headers is not None:
            if not isinstance(headers, dict) or any(not isinstance(k, str) or not isinstance(v, str) for k, v in headers.items()):
                return _err("VALIDATION_ERROR", "headers must be an object of string:string when provided", field="headers")
        if cacheTTLMinutes is not None:
            if not isinstance(cacheTTLMinutes, (int, float)):
                return _err("VALIDATION_ERROR", "cacheTTLMinutes must be a number when provided", field="cacheTTLMinutes")
            if cacheTTLMinutes < 0 or cacheTTLMinutes > 525600:
                return _err("VALIDATION_ERROR", "cacheTTLMinutes must be in [0, 525600]", field="cacheTTLMinutes")
        if filePrefix is not None and not isinstance(filePrefix, str):
            return _err("VALIDATION_ERROR", "filePrefix must be a string when provided", field="filePrefix")
        if fileSuffix is not None and not isinstance(fileSuffix, str):
            return _err("VALIDATION_ERROR", "fileSuffix must be a string when provided", field="fileSuffix")
        return None

    def _fetch(url, hdrs, etag, last_modified):
        req = urllib.request.Request(url, method="GET")
        if hdrs:
            for k, v in hdrs.items():
                req.add_header(k, v)
