            req.add_header("If-None-Match", etag)
        if last_modified:
            req.add_header("If-Modified-Since", last_modified)
        try:
            with urllib.request.urlopen(req, timeout=20) as resp:
                code = getattr(resp, "status", None) or resp.getcode()
                raw = resp.read()
                ct = resp.headers.get("Content-Type")
                et = resp.headers.get("ETag")
                lm = resp.headers.get("Last-Modified")
                return {"ok": True, "status": code, "body": raw, "content_type": ct, "etag": et, "last_modified": lm, "not_modified": False}
        except urllib.error.HTTPError as e:
            if e.code == 304:
                return {"ok": True, "status": 304, "body": b"", "content_type": None, "etag": etag, "last_modified": last_modified, "not_modified": True}
            return {"ok": False, "status": e.code, "error": f"HTTPError {e.code}"}
        except urllib.error.URLError as e:
            return {"ok": False, "status": None, "error": f"URLError {getattr(e, 'reason', e)}"}
        except Exception as e:
            return {"ok": False, "status": None, "error": f"Fetch failed: {e}"}

    def _parse_spec_text(text):
