                return
            ops.append({
                "path": path,
                "method": method.lower(),
                "operationId": op.get("operationId"),
                "summary": op.get("summary") or op.get("description"),
                "tags": op.get("tags") if isinstance(op.get("tags"), list) else []
            })
        if not isinstance(doc, dict):
            return ops
        paths = doc.get("paths")
        if isinstance(paths, dict):
            for path, pitem in paths.items():
                if not isinstance(pitem, dict):
                    continue
                for method in ["get", "post", "put", "patch", "delete", "options", "head", "trace"]:
                    if method in pitem:
                        add_op(path, method, pitem.get(method))
        return ops

    def _apply_tag_filters(ops, inc, exc):
        if inc:
            incs = set(inc)
            ops = [o for o in ops if any(t in incs for t in (o.get("tags") or []))]
        if exc:
            excs = set(exc)
            ops = [o for o in ops if not any(t in excs for t in (o.get("tags") or []))]
        return ops

    err = _validate()
    if err:
        return err

    use_cache = True if useCache is None else bool(useCache)
    skip_val = True if skipValidation is None else bool(skipValidation)
    lazy = False if lazyLoading is None else bool(lazyLoading)

    docs = _load("openapi_documents.json")
    parses = _load("openapi_parses.json")
    jobs = _load("codegen_jobs.json")
    writes = _load("filesystem_writes.json")

    now_iso = _now()
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    url_norm = _normalize_url(swaggerUrl)
    doc = None
    for d in docs:
        if d.get("url_normalized") == url_norm and d.get("status") != "deleted":
            doc = d
            break

    if doc is None:
        doc = {
            "id": _gen_id("doc"),
            "url": swaggerUrl,
            "url_normalized": url_norm,
            "last_request_headers": headers if headers is not None else None,
            "etag": None,
            "last_modified": None,
            "content_type": None,
            "http_status": None,
            "fetch_error": None,
            "raw_bytes": None,
            "raw_body": None,
            "content_sha256": None,
            "openapi_version": None,
            "title": None,
            "version": None,
            "status": "fetching",
            "cache_expires_at": None,
            "last_fetched_at": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        docs.append(doc)
    else:
        if doc.get("status") in ("active", "stale", "failed"):
            doc["status"] = "fetching"
        doc["url"] = swaggerUrl
        if headers is not None:
            doc["last_request_headers"] = headers
        doc["updated_at"] = now_iso

    if cacheTTLMinutes is not None:
        exp = now_dt + datetime.timedelta(minutes=float(cacheTTLMinutes))
        doc["cache_expires_at"] = exp.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    cache_ok = False
    if use_cache and doc.get("raw_body"):
        exp_dt = _parse_dt(doc.get("cache_expires_at"))
        exp_dt = _as_dt_utc(exp_dt) if exp_dt else None
        if exp_dt and exp_dt > now_dt:
            cache_ok = True

    if cache_ok:
        doc["status"] = "active"
        doc["http_status"] = 200
        doc["fetch_error"] = None
        doc["updated_at"] = now_iso
        text = doc.get("raw_body")
    else:
        res = _fetch(swaggerUrl, headers, doc.get("etag"), doc.get("last_modified"))
        doc["http_status"] = res.get("status")
        if res.get("ok") and res.get("not_modified"):
            if not doc.get("raw_body"):
                doc["status"] = "failed"
                doc["fetch_error"] = "Upstream returned 304 but no cached body exists"
                doc["updated_at"] = now_iso
                _save("openapi_documents.json", docs)
                return _err("NOT_FOUND", "No cached content available for 304 response", document_id=doc.get("id"))
            doc["status"] = "active"
            doc["fetch_error"] = None
            doc["updated_at"] = now_iso
            text = doc.get("raw_body")
        elif res.get("ok"):
            body_bytes = res.get("body") or b""
            try:
                text = body_bytes.decode("utf-8")
            except Exception:
                text = body_bytes.decode("latin1", errors="replace")
            doc["etag"] = res.get("etag") or doc.get("etag")
            doc["last_modified"] = res.get("last_modified") or doc.get("last_modified")
            doc["content_type"] = res.get("content_type")
            doc["raw_bytes"] = max(0, len(body_bytes))
            doc["raw_body"] = text
            doc["content_sha256"] = hashlib.sha256(text.encode("utf-8")).hexdigest()
            doc["last_fetched_at"] = now_iso
            doc["fetch_error"] = None
            doc["status"] = "active"
            doc["updated_at"] = now_iso
        else:
            doc["status"] = "failed"
            doc["fetch_error"] = res.get("error")
            doc["updated_at"] = now_iso
            _save("openapi_documents.json", docs)
            return _err("NOT_FOUND", "Failed to fetch swaggerUrl", http_status=doc.get("http_status"), fetch_error=doc.get("fetch_error"), document_id=doc.get("id"))

    pobj, perr = _parse_spec_text(text)
    if perr and not skip_val:
        _save("openapi_documents.json", docs)
        return _err("VALIDATION_ERROR", "OpenAPI document validation failed", details=[perr], document_id=doc["id"])
    if perr and skip_val:
        pobj = {}

    ops = _build_operations_index(pobj)
    ops = _apply_tag_filters(ops, includeTags, excludeTags)

    # parse row (optimized)
    pf_src = {
        "doc_sha": doc.get("content_sha256"),
        "mode": "optimized",
        "for": "api-client",
        "use_cache": use_cache,
        "cache_ttl_minutes": cacheTTLMinutes if cacheTTLMinutes is not None else None,
        "skip_validation": skip_val,
        "lazy_loading": lazy,
        "include_tags": includeTags,
        "exclude_tags": excludeTags
    }
    parse_fingerprint = hashlib.sha256(json.dumps(pf_src, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()
    parse_row = None
    for p in parses:
        if p.get("parse_fingerprint") == parse_fingerprint:
            parse_row = p
            break
    if parse_row is None:
        parse_row = {
            "id": _gen_id("parse"),
            "document_id": doc["id"],
            "mode": "optimized",
            "include_schemas": False,
            "include_details": False,
            "skip_validation": skip_val,
            "use_cache": use_cache,
            "cache_ttl_minutes": cacheTTLMinutes if cacheTTLMinutes is not None else None,
            "lazy_loading": lazy,
            "filter_tag": None,
            "path_prefix": None,
            "parse_fingerprint": parse_fingerprint,
            "operation_count": len(ops),
            "schema_count": 0,
            "operations_index": ops,
            "schemas_blob": None,
            "validation_errors": None if skip_val else ([] if perr is None else [perr]),
            "status": "succeeded" if perr is None or skip_val else "failed",
            "error_message": None if perr is None else perr,
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        parses.append(parse_row)

    # Create job (enforce FK: parse_id references parse for same document_id - true here)
    job = {
        "id": _gen_id("job"),
        "document_id": doc["id"],
        "parse_id": parse_row["id"],
        "job_type": "api-client",
        "tool_variant": "generate-api-client-optimized",
        "output_dir": outputDir if outputDir is not None else None,
        "overwrite": bool(overwrite) if overwrite is not None else False,
        "file_prefix": filePrefix if filePrefix is not None else None,
        "file_suffix": fileSuffix if fileSuffix is not None else None,
        "use_namespace": None,
        "namespace": None,
        "generate_enums": None,
        "strict_types": None,
        "exclude_schemas": None,
        "include_schemas": None,
        "generate_index": None,
        "client_type": clientType,
        "generate_type_imports": bool(generateTypeImports) if generateTypeImports is not None else None,
        "types_import_path": typesImportPath if typesImportPath is not None else None,
        "group_by": groupBy if groupBy is not None else "tag",
        "include_tags": includeTags if includeTags is not None else None,
        "exclude_tags": excludeTags if excludeTags is not None else None,
        "request_headers": headers if headers is not None else None,
        "use_cache": use_cache,
        "cache_ttl_minutes": cacheTTLMinutes if cacheTTLMinutes is not None else None,
        "skip_validation": skip_val,
        "lazy_loading": lazy,
        "template_id": None,
        "status": "running",
        "error_message": None,
        "started_at": now_iso,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    jobs.append(job)

    # Write output file
    base_dir = outputDir if outputDir else "."
    pref = filePrefix or ""
    suf = fileSuffix or ""
    fname = f"{pref}client{suf}.ts"
    file_path = os.path.join(base_dir, fname)

    def _write(job_id, path, text):
        ev = {
            "id": _gen_id("fw"),
            "job_id": job_id,
            "file_path": path,
            "content": text,
            "create_dirs": True,
            "append": False,
            "encoding": "utf8",
            "bytes_written": None,
            "status": "failed",
            "error_message": None,
            "created_at": _now(),
            "updated_at": _now()
        }
        try:
            parent = os.path.dirname(path)
            if parent:
                os.makedirs(parent, exist_ok=True)
            b = text.encode("utf-8")
            with open(path, "wb") as f:
                f.write(b)
            ev["status"] = "succeeded"
            ev["bytes_written"] = len(b)
            ev["updated_at"] = _now()
        except Exception as e:
            ev["status"] = "failed"
            ev["error_message"] = str(e)
            ev["updated_at"] = _now()
        writes.append(ev)
        return ev

    lines = []
    lines.append("/* Generated API client (optimized) */")
    lines.append(f"/* clientType: {clientType} */")
    lines.append(f"/* operations: {len(ops)} */")
    lines.append(f"/* cache: {use_cache} */")
    if generateTypeImports:
        tip = typesImportPath or "./types"
        lines.append(f"import * as Types from '{tip}';")
    lines.append("export const operations = " + json.dumps(ops, ensure_ascii=False, indent=2) + " as const;")
    lines.append("export type Operation = (typeof operations)[number];")
    content = "\n".join(lines) + "\n"

    ev = _write(job["id"], file_path, content)
    if ev["status"] != "succeeded":
        job["status"] = "failed"
        job["error_message"] = ev["error_message"]
        job["finished_at"] = _now()
        job["updated_at"] = _now()
        _save("openapi_documents.json", docs)
        _save("openapi_parses.json", parses)
        _save("codegen_jobs.json", jobs)
        _save("filesystem_writes.json", writes)
        return _err("CONFLICT", "Failed to write generated client file", file_path=file_path, error_message=ev["error_message"], job_id=job["id"])

    job["status"] = "succeeded"
    job["finished_at"] = _now()
    job["updated_at"] = _now()

    _save("openapi_documents.json", docs)
    _save("openapi_parses.json", parses)
    _save("codegen_jobs.json", jobs)
    _save("filesystem_writes.json", writes)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "job": job,
        "document": {"id": doc["id"], "url": doc["url"], "status": doc["status"]},
        "parse": {"id": parse_row["id"], "mode": parse_row["mode"], "operation_count": parse_row["operation_count"]},
        "files": [{"path": file_path, "bytes": ev["bytes_written"]}],
        "meta": {"latency_ms": latency_ms}
    }

def file_writer(filePath, content, createDirs=None, append=None, encoding=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import hashlib
        return f"{prefix}_{hashlib.sha256((prefix + '|' + str(time.time()) + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    # Validate
    if not isinstance(filePath, str) or len(filePath) < 1:
        return _err("VALIDATION_ERROR", "filePath must be a non-empty string", field="filePath")
    if not isinstance(content, str):
        return _err("VALIDATION_ERROR", "content must be a string", field="content")
    if createDirs is not None and not isinstance(createDirs, bool):
        return _err("VALIDATION_ERROR", "createDirs must be a boolean when provided", field="createDirs")
    if append is not None and not isinstance(append, bool):
        return _err("VALIDATION_ERROR", "append must be a boolean when provided", field="append")
    enc = encoding if encoding is not None else "utf8"
    if not isinstance(enc, str):
        return _err("VALIDATION_ERROR", "encoding must be a string when provided", field="encoding")
    if enc not in ("utf8", "utf-8", "ascii", "base64", "latin1", "ucs2", "utf16le"):
        return _err("VALIDATION_ERROR", "encoding must be one of ('utf8','utf-8','ascii','base64','latin1','ucs2','utf16le')", field="encoding")

    cd = True if createDirs is None else bool(createDirs)
    ap = False if append is None else bool(append)

    writes = _load("filesystem_writes.json")
    now_iso = _now()

    ev = {
        "id": _gen_id("fw"),
        "job_id": None,
        "file_path": filePath,
        "content": content,
        "create_dirs": cd,
        "append": ap,
        "encoding": enc,
        "bytes_written": None,
        "status": "failed",
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    try:
        parent = os.path.dirname(filePath)
        if cd and parent:
            os.makedirs(parent, exist_ok=True)

        mode = "ab" if ap else "wb"

        if enc == "base64":
            data = base64.b64decode(content.encode("ascii"), validate=False)
        elif enc in ("utf8", "utf-8"):
            data = content.encode("utf-8")
        elif enc == "ascii":
            data = content.encode("ascii")
        elif enc == "latin1":
            data = content.encode("latin1")
        elif enc == "ucs2":
            # emulate Node's ucs2 as utf-16le
            data = content.encode("utf-16le")
        elif enc == "utf16le":
            data = content.encode("utf-16le")
        else:
            data = content.encode("utf-8")

        with open(filePath, mode) as f:
            f.write(data)

        ev["status"] = "succeeded"
        ev["bytes_written"] = len(data)
        ev["updated_at"] = _now()
    except Exception as e:
        ev["status"] = "failed"
        ev["error_message"] = str(e)
        ev["updated_at"] = _now()

    writes.append(ev)
    _save("filesystem_writes.json", writes)

    if ev["status"] != "succeeded":
        return _err("CONFLICT", "File write failed", filePath=filePath, error_message=ev["error_message"], write_id=ev["id"])

    return {
        "write": {
            "id": ev["id"],
            "file_path": ev["file_path"],
            "bytes_written": ev["bytes_written"],
            "append": ev["append"],
            "encoding": ev["encoding"],
            "status": ev["status"],
            "created_at": ev["created_at"]
        }
    }

def template_list(type=None, framework=None, includeContent=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # No request log collection exists in provided schema; cannot persist observable dynamics.

    t0 = time.time()
    try:
        # Validate inputs
        if type is not None:
            if not isinstance(type, str):
                return _err("VALIDATION_ERROR", "type must be a string")
            if type not in ["all", "api-client", "typescript-types", "config-file"]:
                return _err("VALIDATION_ERROR", "type must be one of: all, api-client, typescript-types, config-file")
        if framework is not None:
            if not isinstance(framework, str):
                return _err("VALIDATION_ERROR", "framework must be a string")
            if framework not in ["axios", "fetch", "react-query", "swr", "angular", "vue"]:
                return _err("VALIDATION_ERROR", "framework must be one of: axios, fetch, react-query, swr, angular, vue")
        if includeContent is not None and not isinstance(includeContent, bool):
            return _err("VALIDATION_ERROR", "includeContent must be a boolean")

        include_content = True if includeContent is None else includeContent

        templates = _load("codegen_templates.json")
        # Only active
        rows = [r for r in templates if isinstance(r, dict) and r.get("status") == "active"]

        # Filter by type
        if type is not None and type != "all":
            rows = [r for r in rows if r.get("type") == type]

        # Filter by framework
        if framework is not None:
            rows = [r for r in rows if r.get("framework") == framework]

        # Response shaping: includeContent=false omits/nulls content without changing stored content
        out = []
        for r in rows:
            rr = dict(r)
            if not include_content:
                rr["content"] = None
            out.append(rr)

        # stable-ish ordering: name asc then id
        def _k(x):
            n = x.get("name")
            return ((n or "").lower(), x.get("id") or "")
        out.sort(key=_k)

        return {
            "templates": out,
            "total": len(out),
            "latency_ms": int((time.time() - t0) * 1000)
        }
    except Exception as e:
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def template_get(id=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "template-get"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(status, error_code=None, template_id=None):
        # Observable dynamics: append to first existing log collection, do not fail the request if none exist.
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                rid = f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{int((time.time()%1)*1e6)}"
                logs.append({
                    "id": rid,
                    "endpoint": endpoint,
                    "credential": None,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": _iso_now(),
                    "template_id": template_id
                })
                _save(fname, logs)
                break

    # Validate
    if id is None or not isinstance(id, str) or not id.strip():
        _log_request("error", "VALIDATION_ERROR", template_id=id)
        return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.", field="id")

    template_id = id.strip()

    # Load templates
    templates = _load("codegen_templates.json")
    if not isinstance(templates, list):
        templates = []

    # Find exact id; if not found, accept that callers may provide other ids and return NOT_FOUND (no extra strictness).
    row = None
    for r in templates:
        if isinstance(r, dict) and r.get("id") == template_id:
            row = r
            break

    if row is None:
        _log_request("error", "NOT_FOUND", template_id=template_id)
        return _err("NOT_FOUND", "Template not found.", id=template_id)

    # Return template as stored (including deleted ones), as the tool is for fetching specific template content.
    _log_request("success", None, template_id=template_id)
    return {
        "template": row,
        "latency_ms": int((time.time() - t0) * 1000)
    }

def template_save(id, name, type, content, framework=None, description=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    try:
        # Validate required
        if not isinstance(id, str) or not id.strip():
            return _err("VALIDATION_ERROR", "id must be a non-empty string")
        if not isinstance(name, str) or not name.strip():
            return _err("VALIDATION_ERROR", "name must be a non-empty string")
        if not isinstance(type, str):
            return _err("VALIDATION_ERROR", "type must be a string")
        if type not in ["api-client", "typescript-types", "config-file"]:
            return _err("VALIDATION_ERROR", "type must be one of: api-client, typescript-types, config-file")
        if not isinstance(content, str) or len(content) <= 0:
            return _err("VALIDATION_ERROR", "content must be a non-empty string")

        # Validate optional
        if framework is not None:
            if not isinstance(framework, str):
                return _err("VALIDATION_ERROR", "framework must be a string")
            if framework not in ["axios", "fetch", "react-query", "swr", "angular", "vue"]:
                return _err("VALIDATION_ERROR", "framework must be one of: axios, fetch, react-query, swr, angular, vue")

        if description is not None and not isinstance(description, str):
            return _err("VALIDATION_ERROR", "description must be a string")

        # Enforce schema/business rules
        # type='typescript-types' implies framework is null
        if type == "typescript-types" and framework is not None:
            return _err("VALIDATION_ERROR", "framework must be null when type is 'typescript-types'")
        # framework non-null => type in ['api-client','config-file']
        if framework is not None and type not in ["api-client", "config-file"]:
            return _err("VALIDATION_ERROR", "framework is only applicable for type 'api-client' or 'config-file'")

        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

        templates = _load("codegen_templates.json")

        existing = None
        existing_idx = None
        for i, r in enumerate(templates):
            if isinstance(r, dict) and r.get("id") == id:
                existing = r
                existing_idx = i
                break

        # Reject updates that would set status='deleted' implicitly:
        # Since save API doesn't accept status, it must not modify status to deleted.
        # If existing is deleted, saving would "reactivate" unless explicitly allowed; treat as conflict.
        if existing is not None and existing.get("status") == "deleted":
            return _err("CONFLICT", "Cannot update a deleted template via template-save")

        # Enforce unique(type, framework, name) where status='active'
        for r in templates:
            if not isinstance(r, dict):
                continue
            if r.get("status") != "active":
                continue
            if r.get("type") == type and r.get("framework") == framework and r.get("name") == name and r.get("id") != id:
                return _err("CONFLICT", "An active template with the same type/framework/name already exists", conflict_with=r.get("id"))

        if existing is None:
            row = {
                "id": id,
                "name": name,
                "type": type,
                "framework": framework,
                "content": content,
                "description": description,
                "is_builtin": False,
                "status": "active",
                "created_at": now,
                "updated_at": now
            }
            templates.append(row)
            _save("codegen_templates.json", templates)
            return {"template": row, "created": True, "latency_ms": int((time.time() - t0) * 1000)}

        # Update existing (preserve is_builtin/status/created_at)
        row = dict(existing)
        row["name"] = name
        row["type"] = type
        row["framework"] = framework
        row["content"] = content
        row["description"] = description
        row["updated_at"] = now

        templates[existing_idx] = row
        _save("codegen_templates.json", templates)
        return {"template": row, "created": False, "latency_ms": int((time.time() - t0) * 1000)}
    except Exception as e:
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def template_delete(id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    try:
        if not isinstance(id, str) or not id.strip():
            return _err("VALIDATION_ERROR", "id must be a non-empty string")

        templates = _load("codegen_templates.json")
        idx = None
        row = None
        for i, r in enumerate(templates):
            if isinstance(r, dict) and r.get("id") == id:
                idx = i
                row = r
                break

        if row is None:
            return _err("NOT_FOUND", "Template not found")

        if row.get("status") == "deleted":
            # Idempotent soft-delete
            return {
                "deleted": True,
                "template": row,
                "latency_ms": int((time.time() - t0) * 1000)
            }

        if row.get("is_builtin") is True:
            return _err("CONFLICT", "Built-in templates cannot be deleted")

        # Conflict if referenced by an active generation job
        jobs = _load("codegen_jobs.json")
        active_statuses = set(["queued", "running"])
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("template_id") == id and j.get("status") in active_statuses:
                return _err("CONFLICT", "Template is referenced by an active generation job", job_id=j.get("id"))

        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        new_row = dict(row)
        # lifecycle transition active -> deleted allowed; others not (but we handled already deleted)
        if new_row.get("status") != "active":
            return _err("INVALID_TRANSITION", "Template cannot be deleted from its current status", status=new_row.get("status"))
        new_row["status"] = "deleted"
        new_row["updated_at"] = now

        templates[idx] = new_row
        _save("codegen_templates.json", templates)

        return {
            "deleted": True,
            "template": new_row,
            "latency_ms": int((time.time() - t0) * 1000)
        }
    except Exception as e:
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def document_list(status=None, url=None, urlNormalized=None, contentSha256=None, includeDeleted=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # Request log (best-effort; schema doesn't define one). Keep dynamics via a local file.
    reqlog_file = "request_logs.json"
    reqlogs = _load(reqlog_file)

    def _log(status_code, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        reqlogs.append({
            "id": f"req_{int(time.time()*1000)}_{len(reqlogs)+1}",
            "endpoint": "document-list",
            "timestamp": now_iso,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
        })
        _save(reqlog_file, reqlogs)

    # Validate inputs
    allowed_status = {"active", "fetching", "stale", "failed", "deleted"}
    allowed_sort = {"created_at", "updated_at", "last_fetched_at"}
    allowed_order = {"asc", "desc"}

    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'status' value.", allowed=list(sorted(allowed_status)))
    if url is not None and not isinstance(url, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'url' type; expected string.")
    if urlNormalized is not None and not isinstance(urlNormalized, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'urlNormalized' type; expected string.")
    if contentSha256 is not None and not isinstance(contentSha256, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'contentSha256' type; expected string.")
    if includeDeleted is not None and not isinstance(includeDeleted, bool):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'includeDeleted' type; expected boolean.")
    if limit is not None:
        if not isinstance(limit, int):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'limit' type; expected integer.")
        if limit < 1 or limit > 200:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'limit' range; must be between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'cursor' type; expected string.")
    if sort is not None:
        if not isinstance(sort, str) or sort not in allowed_sort:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'sort' value.", allowed=list(sorted(allowed_sort)))
    if order is not None:
        if not isinstance(order, str) or order not in allowed_order:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'order' value.", allowed=list(sorted(allowed_order)))

    # Defaults
    if limit is None:
        limit = 50
    if sort is None:
        sort = "updated_at"
    if order is None:
        order = "desc"
    if includeDeleted is None:
        includeDeleted = False

    # Cursor decode: base64 JSON: {"offset": int}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                _log(400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = obj["offset"]
        except (ValueError, json.JSONDecodeError):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor encoding.")

    docs = _load("openapi_documents.json")
    if not isinstance(docs, list):
        docs = []

    # Filtering
    out = []
    for d in docs:
        if not isinstance(d, dict):
            continue
        if not includeDeleted and d.get("status") == "deleted":
            continue
        if status is not None and d.get("status") != status:
            continue
        if url is not None and d.get("url") != url:
            continue
        if urlNormalized is not None and d.get("url_normalized") != urlNormalized:
            continue
        if contentSha256 is not None and d.get("content_sha256") != contentSha256:
            continue
        out.append(d)

    total = len(out)

    # Sorting with nulls last (for asc) / first (for desc) consistently
    def _key(v):
        x = v.get(sort)
        # Expect ISO string or None; keep stable
        if x is None:
            return (1, "")
        if isinstance(x, str):
            return (0, x)
        return (0, str(x))

    reverse = (order == "desc")
    try:
        out.sort(key=_key, reverse=reverse)
    except TypeError:
        # Fallback to string coercion
        out.sort(key=lambda v: str(v.get(sort)), reverse=reverse)

    # Pagination
    page = out[offset: offset + limit]
    has_more = offset + limit < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": offset + limit}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    _log(200, None)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
        }
    }

