def document_refresh(id, headers=None, useCache=None, cacheTTLMinutes=None, **_extra):
    import json, os, datetime, hashlib, urllib.parse, urllib.request, urllib.error, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "document-refresh"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        st = s.strip()
        try:
            if st.endswith("Z"):
                return datetime.datetime.fromisoformat(st[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(st)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _safe_headers(h):
        if h is None:
            return {}
        if not isinstance(h, dict):
            return None
        out = {}
        for k, v in h.items():
            if not isinstance(k, str) or not k:
                return None
            if not isinstance(v, str):
                return None
            out[k] = v
        return out

    def _log_request(status, error_code=None, document_id=None):
        latency_ms = int((time.time() - t0) * 1000)
        ts = _iso(_now_dt())
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                rid = f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{int((time.time()%1)*1e6)}"
                logs.append({
                    "id": rid,
                    "endpoint": endpoint,
                    "credential": None,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": latency_ms,
                    "timestamp": ts,
                    "document_id": document_id
                })
                _save(fname, logs)
                break

    # ---- validate ----
    if not isinstance(id, str) or not id.strip():
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.", field="id")
    hdrs = _safe_headers(headers)
    if hdrs is None:
        _log_request("error", "VALIDATION_ERROR", document_id=id)
        return _err("VALIDATION_ERROR", "Parameter 'headers' must be an object of string values.", field="headers")
    if useCache is not None and not isinstance(useCache, bool):
        _log_request("error", "VALIDATION_ERROR", document_id=id)
        return _err("VALIDATION_ERROR", "Parameter 'useCache' must be boolean.", field="useCache")
    if cacheTTLMinutes is not None:
        if not isinstance(cacheTTLMinutes, int) or isinstance(cacheTTLMinutes, bool):
            _log_request("error", "VALIDATION_ERROR", document_id=id)
            return _err("VALIDATION_ERROR", "Parameter 'cacheTTLMinutes' must be an integer.", field="cacheTTLMinutes")
        if cacheTTLMinutes < 0 or cacheTTLMinutes > 525600:
            _log_request("error", "VALIDATION_ERROR", document_id=id)
            return _err("VALIDATION_ERROR", "cacheTTLMinutes must be in [0, 525600].", field="cacheTTLMinutes")

    docs = _load("openapi_documents.json")
    doc = None
    doc_idx = None
    for i, r in enumerate(docs):
        if isinstance(r, dict) and r.get("id") == id:
            doc = r
            doc_idx = i
            break
    if doc is None:
        _log_request("error", "NOT_FOUND", document_id=id)
        return _err("NOT_FOUND", "OpenAPI document not found.", id=id)

    # lifecycle transition to fetching must be legal
    transitions = {
        "fetching": {"active", "failed"},
        "active": {"stale", "deleted", "fetching"},
        "stale": {"fetching", "deleted"},
        "failed": {"fetching", "deleted"},
        "deleted": set(),
    }
    cur = doc.get("status")
    if cur not in transitions:
        _log_request("error", "VALIDATION_ERROR", document_id=id)
        return _err("VALIDATION_ERROR", "Document has an invalid status in datastore.", id=id, status=cur)
    if cur == "deleted":
        _log_request("error", "INVALID_TRANSITION", document_id=id)
        return _err("INVALID_TRANSITION", "Cannot refresh a deleted document.", id=id)
    if cur != "fetching" and "fetching" not in transitions[cur]:
        _log_request("error", "INVALID_TRANSITION", document_id=id)
        return _err("INVALID_TRANSITION", f"Cannot transition document from {cur} to fetching.", id=id)

    now = _now_dt()

    # optional cache reuse
    allow_cache = True if useCache is None else bool(useCache)
    exp = _parse_dt(doc.get("cache_expires_at"))
    cache_ok = False
    if allow_cache and exp is not None and exp > now and isinstance(doc.get("raw_body"), str) and doc.get("raw_body") != "":
        cache_ok = True

    # set fetching and persist immediately
    if cur != "fetching":
        doc["status"] = "fetching"
    doc["last_request_headers"] = hdrs or doc.get("last_request_headers")
    doc["updated_at"] = _iso(now)
    docs[doc_idx] = doc
    _save("openapi_documents.json", docs)

    if cache_ok:
        # treat as refresh success without refetch
        if cacheTTLMinutes is not None:
            doc["cache_expires_at"] = _iso(now + datetime.timedelta(minutes=int(cacheTTLMinutes)))
        doc["status"] = "active"
        doc["fetch_error"] = None
        doc["updated_at"] = _iso(now)
        docs[doc_idx] = doc
        _save("openapi_documents.json", docs)
        _log_request("success", None, document_id=id)
        return {"document": doc, "used_cache": True, "latency_ms": int((time.time() - t0) * 1000)}

    # otherwise refetch
    url = doc.get("url")
    if not isinstance(url, str) or not url.strip():
        doc["status"] = "failed"
        doc["fetch_error"] = "Document has no URL to fetch."
        doc["updated_at"] = _iso(now)
        docs[doc_idx] = doc
        _save("openapi_documents.json", docs)
        _log_request("error", "VALIDATION_ERROR", document_id=id)
        return _err("VALIDATION_ERROR", "Document record is missing a fetchable URL.", id=id)

    body_text = None
    content_type = None
    http_status = None
    fetch_error = None
    etag = None
    last_modified = None

    try:
        req = urllib.request.Request(url, headers=hdrs, method="GET")
        with urllib.request.urlopen(req, timeout=25) as resp:
            http_status = getattr(resp, "status", None)
            if http_status is None:
                try:
                    http_status = resp.getcode()
                except Exception:
                    http_status = 200
            content_type = resp.headers.get("Content-Type")
            etag = resp.headers.get("ETag")
            last_modified = resp.headers.get("Last-Modified")
            raw = resp.read()
            try:
                body_text = raw.decode("utf-8")
            except UnicodeDecodeError:
                body_text = raw.decode("latin1")
    except urllib.error.HTTPError as e:
        http_status = int(getattr(e, "code", 0) or 0) or None
        fetch_error = f"Upstream returned HTTP {getattr(e, 'code', '')}".strip()
    except urllib.error.URLError as e:
        fetch_error = f"Fetch failed: {getattr(e, 'reason', str(e))}"
    except Exception as e:
        fetch_error = f"Fetch failed: {str(e)}"

    if body_text is None or fetch_error is not None or (http_status is not None and http_status >= 400):
        doc["http_status"] = http_status
        doc["fetch_error"] = fetch_error or (f"Upstream returned HTTP {http_status}" if http_status else "Fetch failed")
        doc["status"] = "failed"
        doc["updated_at"] = _iso(now)
        docs[doc_idx] = doc
        _save("openapi_documents.json", docs)
        _log_request("error", "NOT_FOUND", document_id=id)
        return _err("NOT_FOUND", "OpenAPI document could not be retrieved from the stored URL.", id=id, url=url, http_status=http_status, fetch_error=doc["fetch_error"])

    sha = hashlib.sha256(body_text.encode("utf-8")).hexdigest()
    doc["raw_body"] = body_text
    doc["raw_bytes"] = len(body_text.encode("utf-8", errors="replace"))
    doc["content_sha256"] = sha
    doc["content_type"] = content_type
    doc["http_status"] = http_status
    doc["fetch_error"] = None
    doc["etag"] = etag
    doc["last_modified"] = last_modified
    doc["last_fetched_at"] = _iso(now)
    doc["status"] = "active"
    if cacheTTLMinutes is not None:
        doc["cache_expires_at"] = _iso(now + datetime.timedelta(minutes=int(cacheTTLMinutes)))
    doc["updated_at"] = _iso(now)

    docs[doc_idx] = doc
    _save("openapi_documents.json", docs)
    _log_request("success", None, document_id=id)
    return {"document": doc, "used_cache": False, "latency_ms": int((time.time() - t0) * 1000)}

def parse_get(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
