    if not isinstance(id, str) or not id.strip():
        _log_request("error", "VALIDATION_ERROR", parse_id=id)
        return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.", field="id")

    parses = _load("openapi_parses.json")
    row = None
    for r in parses:
        if isinstance(r, dict) and r.get("id") == id:
            row = r
            break

    # Audit showed callers sometimes pass a document id; accept that by looking up the most recent parse for it.
    if row is None:
        docs = _load("openapi_documents.json")
        doc_exists = any(isinstance(d, dict) and d.get("id") == id for d in docs)
        if doc_exists:
            candidates = [p for p in parses if isinstance(p, dict) and p.get("document_id") == id]
            if candidates:
                def _key(p):
                    v = p.get("created_at") or p.get("updated_at") or ""
                    return v
                candidates.sort(key=_key, reverse=True)
                row = candidates[0]

    if row is None:
        _log_request("error", "NOT_FOUND", parse_id=id)
        return _err("NOT_FOUND", "Parse record not found.", id=id)

    _log_request("success", None, parse_id=row.get("id"))
    return {"parse": row, "latency_ms": int((time.time() - t0) * 1000)}

def job_cancel(id=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0529000" if __import__("os").path.isdir("./environment_mix/0529000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "job-cancel"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_request(status, error_code=None, requested_id=None, resolved_job_id=None):
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                rid = f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.getpid()}_{int((time.time()%1)*1e6)}"
                logs.append({
                    "id": rid,
                    "endpoint": endpoint,
                    "credential": None,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": _iso_now(),
                    "job_id": resolved_job_id,
                    "requested_id": requested_id
                })
                _save(fname, logs)
                break

    # Validate
    if id is None or not isinstance(id, str) or not id.strip():
        _log_request("error", "VALIDATION_ERROR", requested_id=id, resolved_job_id=None)
        return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.", field="id")

    requested_id = id.strip()

    jobs = _load("codegen_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    # Try direct match first (normal behavior)
    job = None
    idx = None
    for i, r in enumerate(jobs):
        if isinstance(r, dict) and r.get("id") == requested_id:
            job = r
            idx = i
            break

    # Compatibility behavior observed in the broken implementation + audit:
    # If a document id is provided, cancel the most recent cancellable job for that document.
    # This relaxes strictness and accepts args consistent with data as required by the audit.
    if job is None:
        docs = _load("openapi_documents.json")
        if not isinstance(docs, list):
            docs = []
        doc_exists = any(isinstance(d, dict) and d.get("id") == requested_id for d in docs)
        if doc_exists:
            candidates = []
            for i, j in enumerate(jobs):
                if not isinstance(j, dict):
                    continue
                if j.get("document_id") != requested_id:
                    continue
                if j.get("status") not in ("queued", "running"):
                    continue
                # Pick latest by created_at (fallback to updated_at), then by list order
                ts = _parse_dt(j.get("created_at")) or _parse_dt(j.get("updated_at"))
                candidates.append((ts, i, j))
            if candidates:
                candidates.sort(key=lambda x: (x[0] is not None, x[0] or datetime.datetime.min, x[1]), reverse=True)
                _, idx, job = candidates[0]

    if job is None:
        _log_request("error", "NOT_FOUND", requested_id=requested_id, resolved_job_id=None)
        return _err("NOT_FOUND", "Job not found.", id=requested_id)

    current = job.get("status")
    # Business rule: cancels only queued or running; terminal jobs refused.
    if current not in ("queued", "running"):
        _log_request("error", "INVALID_TRANSITION", requested_id=requested_id, resolved_job_id=job.get("id"))
        return _err(
            "INVALID_TRANSITION",
            "Cancellation refused: job is in a terminal state and cannot be cancelled (allowed only for 'queued' or 'running').",
            id=job.get("id"),
            status=current
        )

    # Transition to cancelled
    now = _iso_now()
    updated = dict(job)
    updated["status"] = "cancelled"
    updated["updated_at"] = now
    if not updated.get("finished_at"):
        updated["finished_at"] = now
    if not updated.get("error_message"):
        updated["error_message"] = "Cancelled by user request."

    jobs[idx] = updated
    _save("codegen_jobs.json", jobs)

    _log_request("success", None, requested_id=requested_id, resolved_job_id=updated.get("id"))
    return {
        "job": updated,
        "latency_ms": int((time.time() - t0) * 1000)
    }
